export default App;

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { ProcessedTask } from '../types';

interface GanttChartProps {
  tasks: ProcessedTask[];
  baselineTasks?: ProcessedTask[]; // Ghost main
  baselineRealisticTasks?: ProcessedTask[]; // Ghost realistic
  baselineMaxVelocityTasks?: ProcessedTask[]; // Ghost max velocity
  realisticTasks?: ProcessedTask[];
  maxVelocityTasks?: ProcessedTask[];
  weekendHours: number;
  isDarkMode?: boolean;
  isPdfExport?: boolean;
  bufferPercent?: number;
  projectStartDate: Date;
  currentDate?: Date;
  onTaskToggle?: (taskId: string) => void;
  isExecutionMode?: boolean;
}

export const GanttChart: React.FC<GanttChartProps> = ({ 
  tasks, 
  baselineTasks,
  baselineRealisticTasks,
  baselineMaxVelocityTasks,
  realisticTasks, 
  maxVelocityTasks, 
  weekendHours, 
  isDarkMode = false,
  isPdfExport = false,
  bufferPercent = 30,
  projectStartDate,
  currentDate,
  onTaskToggle,
  isExecutionMode = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Tooltip State for Fixed Positioning (Solves Z-Index clipping)
  const [activeTooltip, setActiveTooltip] = useState<{
    x: number;
    y: number;
    task: ProcessedTask;
    realistic?: ProcessedTask;
  } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 640);

    // Check on mount
    if (typeof window !== 'undefined') {
        checkMobile();
        window.addEventListener('resize', checkMobile);
    }
    return () => {
        if (typeof window !== 'undefined') window.removeEventListener('resize', checkMobile);
    }
  }, []);

  // Metrics for rendering - Condensed if exporting to PDF or on Mobile
  const DAY_WIDTH = isPdfExport ? 25 : (isMobile ? 40 : 60);
  const HEADER_HEIGHT = 54;
  const ROW_HEIGHT = 52; 
  // Reduced sidebar width slightly since we are truncating names
  const SIDEBAR_WIDTH = isPdfExport ? 140 : (isMobile ? 50 : 200); 

  // VISUAL ADJUSTMENT: Start the chart 1 day before the actual Project Start Date
  const VISUAL_SHIFT_DAYS = 1;

  // Helper to find the max day extent across a set of tasks
  const getEndDay = (taskList?: ProcessedTask[]) => 
    taskList ? taskList.reduce((acc, t) => Math.max(acc, t.startOffsetDays + t.durationDays), 0) : 0;

  // Calculate total days including all possible scenarios (Ghosts, Realistic, Max Vel)
  const effectiveMaxDay = Math.max(
      getEndDay(tasks),
      getEndDay(realisticTasks),
      getEndDay(baselineTasks),
      getEndDay(baselineRealisticTasks),
      getEndDay(maxVelocityTasks),
      getEndDay(baselineMaxVelocityTasks)
  );

  const totalDays = effectiveMaxDay + 4 + VISUAL_SHIFT_DAYS; // Add ample buffer + shift
  const chartWidth = totalDays * DAY_WIDTH;
  const totalWidth = SIDEBAR_WIDTH + chartWidth;

  // Calculate Today's position using passed currentDate or default to now
  const now = currentDate || new Date();
  const diffTime = now.getTime() - projectStartDate.getTime();
  const nowOffsetDays = (diffTime / (1000 * 60 * 60 * 24)) + VISUAL_SHIFT_DAYS;
  const showNowLine = nowOffsetDays >= 0 && nowOffsetDays <= totalDays;

  // Helper to format render dates
  const getDateLabel = (dayOffset: number) => {
    // Use the projectStartDate as the anchor
    const d = new Date(projectStartDate);
    d.setDate(d.getDate() + dayOffset - VISUAL_SHIFT_DAYS);
    return {
      weekday: d.toLocaleDateString('en-US', { weekday: 'short' }),
      day: d.getDate(),
      month: d.toLocaleDateString('en-US', { month: 'short' }),
      isWeekend: d.getDay() === 0 || d.getDay() === 6
    };
  };

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-500 border-purple-600';
    if (phase.includes('Frontend')) return 'bg-blue-500 border-blue-600';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-500 border-indigo-600';
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-500 border-rose-600';
    if (phase.includes('Deployment')) return 'bg-emerald-500 border-emerald-600';
    if (phase.includes('User')) return 'bg-amber-500 border-amber-600';
    return isDarkMode ? 'bg-slate-600 border-slate-700' : 'bg-slate-500 border-slate-600';
  };

  return (
    <div className={`gantt-container bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col ${isExecutionMode ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4">
        <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 whitespace-nowrap">Timeline & Dependencies</h3>
            {isExecutionMode && (
                <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-sm uppercase tracking-wider animate-pulse">
                    Execution Mode
                </span>
            )}
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs w-full xl:w-auto xl:justify-end">
           {/* Schedule Types */}
           <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-4 mr-2">
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-emerald-500 rounded-sm"></span> Realistic ({bufferPercent}% Buffer)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-rose-500 rounded-sm"></span> Max Velocity (10h/5h)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-black dark:bg-slate-200 rounded-sm"></span> Done
                </div>
           </div>

           {/* Phase Legend */}
           <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-purple-500 rounded-sm"></span> Design
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></span> Frontend
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-indigo-500 rounded-sm"></span> Logic
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-rose-500 rounded-sm"></span> QA
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm"></span> Deploy
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-amber-500 rounded-sm"></span> Outreach
                </div>
           </div>
        </div>
      </div>

      <div className="gantt-scroll-area overflow-x-auto" ref={containerRef}>
        <div 
            className="flex relative" 
            style={{ 
                width: totalWidth,
                height: (tasks.length * ROW_HEIGHT) + HEADER_HEIGHT + 20 
            }}
        >
            {/* Left Column: Task Names (Frozen/Sticky) */}
            <div 
              style={{ width: SIDEBAR_WIDTH }}
              className="sticky left-0 flex-shrink-0 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-30 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_12px_-4px_rgba(0,0,0,0.3)] transition-all duration-300"
            >
            <div style={{ height: HEADER_HEIGHT }} className={`sticky top-0 z-40 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 p-2 font-bold text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center ${isMobile ? 'justify-center' : ''}`}>
                {isMobile ? '#' : 'Task Name'}
            </div>
            {tasks.map((task) => {
                // Shorten task name to 3 words
                const words = task.task_name.split(' ');
                const shortName = words.slice(0, 3).join(' ') + (words.length > 3 ? '...' : '');

                // Dependency Logic: Lock if not completed AND has unfinished predecessors
                const hasUnfinishedPredecessors = task.predecessors.some(predId => {
                    const pred = tasks.find(t => t.id === predId);
                    return pred && !pred.isCompleted;
                });

                const isDependencyLocked = !task.isCompleted && hasUnfinishedPredecessors;

                // Visual dimming for text when in Execution Mode (to highlight the checkbox is the only active thing)
                // But only if not Done. If Done, it's already struck through.
                const textOpacityClass = isExecutionMode && !task.isCompleted ? 'opacity-80' : '';

                return (
                    <div 
                    key={task.id} 
                    style={{ height: ROW_HEIGHT }} 
                    className={`border-b border-slate-100 dark:border-slate-800 px-3 flex items-center text-xs font-medium text-slate-700 dark:text-slate-300 ${isMobile ? 'justify-center' : ''}`}
                    title={task.task_name}
                    >
                        {isMobile ? (
                            <span 
                                onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                className={`font-bold ${isDependencyLocked ? 'text-slate-300' : 'text-slate-600 dark:text-slate-300 cursor-pointer'}`}
                            >
                                {task.id}
                            </span>
                        ) : (
                            <div className="flex items-center w-full min-w-0 gap-2">
                                {/* Done Toggle */}
                                <button 
                                    onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                    disabled={isDependencyLocked}
                                    title={isDependencyLocked ? "Complete predecessors first" : (task.isCompleted ? "Mark as Not Done" : "Mark as Done")}
                                    className={`w-4 h-4 rounded-full border flex-shrink-0 flex items-center justify-center transition-all ${
                                        isDependencyLocked 
                                          ? 'border-slate-200 bg-slate-100 dark:bg-slate-800 dark:border-slate-700 cursor-not-allowed opacity-50' 
                                          : task.isCompleted 
                                            ? 'bg-black dark:bg-slate-200 border-black dark:border-slate-200 ring-2 ring-offset-2 ring-indigo-500 dark:ring-indigo-400 dark:ring-offset-slate-900' 
                                            : `border-slate-300 hover:border-slate-400 dark:border-slate-600 dark:hover:border-slate-500 ${isExecutionMode ? 'ring-2 ring-indigo-500/20 scale-110' : ''}`
                                    }`}
                                >
                                    {task.isCompleted && (
                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-2.5 h-2.5 text-white dark:text-slate-900">
                                            <path fillRule="evenodd" d="M19.916 4.626a.75.75 0 01.208 1.04l-9 13.5a.75.75 0 01-1.154.114l-6-6a.75.75 0 011.06-1.06l5.353 5.353 8.493-12.739a.75.75 0 011.04-.208z" clipRule="evenodd" />
                                        </svg>
                                    )}
                                    {isDependencyLocked && (
                                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-2.5 h-2.5 text-slate-300 dark:text-slate-600">
                                            <path fillRule="evenodd" d="M12 1.5a5.25 5.25 0 00-5.25 5.25v3a3 3 0 00-3 3v6.75a3 3 0 003 3h10.5a3 3 0 003-3v-6.75a3 3 0 00-3-3v-3c0-2.9-2.35-5.25-5.25-5.25zm3.75 8.25v-3a3.75 3.75 0 10-7.5 0v3h7.5z" clipRule="evenodd" />
                                        </svg>
                                    )}
                                </button>

                                <span 
                                    onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                    className={`mr-1 font-mono flex-shrink-0 transition-colors duration-200 ${
                                        task.isCompleted 
                                        ? 'text-slate-300 line-through cursor-pointer hover:text-slate-500' 
                                        : (isDependencyLocked 
                                            ? 'text-slate-300 dark:text-slate-600 cursor-not-allowed' 
                                            : `text-slate-400 dark:text-slate-600 cursor-pointer hover:text-indigo-600 dark:hover:text-indigo-400 hover:font-bold ${textOpacityClass}`)
                                    }`}
                                >
                                    {task.id}.
                                </span> 
                                <span className={`truncate transition-opacity ${task.isCompleted ? 'text-slate-400 line-through' : (isDependencyLocked ? 'text-slate-400 dark:text-slate-600' : textOpacityClass)}`}>
                                    {shortName}
                                </span>
                            </div>
                        )}
                    </div>
                );
            })}
            </div>

            {/* Right Column: Chart Area */}
            <div className="flex-1 relative h-full">

                {/* Timeline Header (Sticky Top) */}
                <div className="flex sticky top-0 left-0 right-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 z-20" style={{ height: HEADER_HEIGHT }}>
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { day, month, weekday, isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 flex flex-col items-center justify-center text-[10px] border-r border-slate-200 dark:border-slate-800 leading-tight ${
                            isZeroWorkWeekend ? 'bg-slate-200 dark:bg-slate-950 text-slate-400 dark:text-slate-600' : 
                            isWeekend ? 'bg-slate-100 dark:bg-slate-900' : ''
                        }`}
                    >
                        <span className="text-[9px] uppercase font-bold text-slate-500 dark:text-slate-400">{weekday}</span>
                        <span className="font-bold text-slate-800 dark:text-slate-200 text-xs">{day}</span>
                        <span className="text-[9px] text-slate-400 dark:text-slate-500">{month}</span>
                    </div>
                    );
                })}
                </div>

                {/* Grid Background */}
                <div className="absolute top-0 bottom-0 left-0 right-0 z-0 flex pointer-events-none">
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 border-r border-dashed border-slate-300 dark:border-slate-800 h-full ${
                            isZeroWorkWeekend ? 'bg-slate-100 dark:bg-slate-950/50' : 
                            isWeekend ? 'bg-slate-50/50 dark:bg-slate-900/30' : ''
                        }`}
                    />
                    );
                })}
                </div>

                {/* Current Date Line */}
                {showNowLine && (
                    <div 
                        className="absolute bottom-0 border-l-2 border-dashed border-amber-500 z-50 pointer-events-none"
                        style={{ 
                            left: Math.max(nowOffsetDays * DAY_WIDTH, 0),
                            top: HEADER_HEIGHT, 
                        }}
                    >
                        <div 
                            className="absolute -top-3 text-[9px] font-bold text-white bg-amber-600 dark:bg-amber-500 px-2 py-1 rounded shadow-md whitespace-nowrap ring-2 ring-white dark:ring-slate-900 z-50 transition-transform duration-300"
                            style={{
                                left: 0,
                                transform: nowOffsetDays * DAY_WIDTH < 25 ? 'none' : 'translateX(-50%)'
                            }}
                        >
                            Today
                        </div>
                    </div>
                )}

                {/* Dependency Lines (SVG Layer) */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ marginTop: HEADER_HEIGHT }}>
                <defs>
                    <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                    <polygon points="0 0, 6 2, 0 4" fill={isDarkMode ? "#64748b" : "#94a3b8"} />
                    </marker>
                </defs>
                {tasks.map(task => 
                    task.predecessors.map(predId => {
                    const pred = tasks.find(p => p.id === predId);
                    if (!pred) return null;

                    // Coordinates
                    // We target the center of the main bar (top: 16, height: 20 -> center 26)
                    // SHIFT: Add VISUAL_SHIFT_DAYS to offsets
                    const startX = (pred.startOffsetDays + pred.durationDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const startY = (pred.rowIndex * ROW_HEIGHT) + 26; 
                    const endX = (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const endY = (task.rowIndex * ROW_HEIGHT) + 26;

                    // Curve logic
                    const gap = endX - startX;
                    const midX = startX + (gap > 20 ? 15 : gap/2);

                    return (
                        <path
                        key={`${pred.id}-${task.id}`}
                        d={`M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${endY} L ${endX} ${endY}`}
                        fill="none"
                        stroke={isDarkMode ? "#64748b" : "#94a3b8"}
                        strokeWidth="1.5"
                        strokeDasharray="3 3"
                        markerEnd="url(#arrowhead)"
                        className="transition-all duration-300 opacity-50"
                        />
                    );
                    })
                )}
                </svg>

                {/* Task Bars */}
                <div className="absolute top-0 left-0 w-full z-10" style={{ marginTop: HEADER_HEIGHT }}>
                {tasks.map((task) => {
                    // Find corresponding realistic task
                    const realistic = realisticTasks?.find(t => t.id === task.id);
                    // Find corresponding max velocity task
                    const maxVel = maxVelocityTasks?.find(t => t.id === task.id);

                    // Find corresponding baseline task (Ghost Main)
                    const baseline = baselineTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline realistic (Ghost Realistic)
                    const baselineRealistic = baselineRealisticTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline max velocity (Ghost Max Vel - Immutable)
                    const baselineMaxVel = baselineMaxVelocityTasks?.find(t => t.id === task.id);

                    const isDone = task.isCompleted;

                    return (
                        <div
                        key={task.id}
                        style={{
                            height: ROW_HEIGHT,
                            width: '100%',
                            position: 'relative'
                        }}
                        >
                        {/* 1. Ghost Realistic Bar (Green Dashed) - Top symmetric (6px) */}
                        {baselineRealistic && (
                            <div
                                className="absolute rounded-sm border border-emerald-300 dark:border-emerald-700/50 bg-emerald-100/30 dark:bg-emerald-900/10 pointer-events-none"
                                style={{
                                    left: (baselineRealistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineRealistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6, 
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 2. Ghost Max Velocity Bar (Red Dashed) - Bottom symmetric (42px) */}
                        {baselineMaxVel && (
                             <div
                                className="absolute rounded-sm border border-rose-300 dark:border-rose-700/50 bg-rose-100/30 dark:bg-rose-900/10 pointer-events-none"
                                style={{
                                    left: (baselineMaxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineMaxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 3. Ghost Main Bar (Gray Dashed) - Center symmetric (19px) */}
                        {baseline && (
                             <div
                                className="absolute rounded-sm bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 pointer-events-none"
                                style={{
                                    left: (baseline.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baseline.durationDays * DAY_WIDTH, 4),
                                    height: 14,
                                    top: 19,
                                    opacity: 0.5,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 4. Live Max Velocity Bar (Red Solid) - Bottom symmetric (42px) */}
                        {!isDone && maxVel && (
                             <div
                                className="absolute rounded-sm bg-rose-400/80 dark:bg-rose-500/80 pointer-events-none z-10"
                                style={{
                                    left: (maxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(maxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                }}
                            />
                        )}

                         {/* 5. Live Realistic Bar (Green Solid) - Top symmetric (6px) */}
                         {!isDone && realistic && (
                             <div
                                className="absolute rounded-sm bg-emerald-400/80 dark:bg-emerald-500/80 pointer-events-none z-10"
                                style={{
                                    left: (realistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(realistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6,
                                }}
                            />
                        )}

                        {/* 6. MAIN TASK BAR - Center (16px) */}
                        <div
                            className={`absolute rounded shadow-sm border flex items-center justify-center z-20 group cursor-help transition-all duration-300 ${
                                isDone 
                                ? 'bg-black dark:bg-slate-200 border-black dark:border-slate-200' 
                                : getPhaseColor(task.phase)
                            }`}
                            style={{
                                left: (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                width: Math.max(task.durationDays * DAY_WIDTH, 4),
                                height: 20,
                                top: 16,
                            }}
                            onMouseEnter={(e) => {
                                const rect = e.currentTarget.getBoundingClientRect();
                                setActiveTooltip({
                                    x: rect.left + (rect.width / 2),
                                    y: rect.top,
                                    task,
                                    realistic
                                });
                            }}
                            onMouseLeave={() => setActiveTooltip(null)}
                        >
                             {/* Label inside bar if wide enough */}
                             {(task.durationDays * DAY_WIDTH) > 60 && (
                                <span className={`text-[9px] font-bold truncate px-2 ${isDone ? 'text-white dark:text-slate-900' : 'text-white'}`}>
                                    {isDone ? 'DONE' : `${task.duration_hours}h`}
                                </span>
                             )}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* PORTALED TOOLTIP OVERLAY */}
      {activeTooltip && typeof document !== 'undefined' && createPortal(
            <div 
                className="fixed z-[9999] pointer-events-none print:hidden"
                style={{ 
                    left: activeTooltip.x, 
                    top: activeTooltip.y,
                    transform: 'translate(-50%, -100%)',
                    marginTop: '-8px'
                }}
            >
                <div className="bg-slate-900 text-white text-xs rounded-lg p-3 shadow-xl w-48 border border-slate-700">
                    <div className="font-bold mb-1">{activeTooltip.task.task_name}</div>
                    <div className="text-slate-400 mb-2">{activeTooltip.task.phase}</div>
                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                            <span className="block text-slate-500">Start</span>
                            {activeTooltip.task.startDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">End</span>
                            {activeTooltip.task.endDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">Duration</span>
                            {activeTooltip.task.duration_hours}h
                        </div>
                        {!activeTooltip.task.isCompleted && activeTooltip.realistic && (
                            <div>
                                <span className="block text-emerald-400">Realistic End</span>
                                {activeTooltip.realistic.endDate.toLocaleDateString()}
                            </div>
                        )}
                    </div>
                </div>
                {/* Triangle */}
                <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900 mx-auto"></div>
            </div>,
            document.body
       )}
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { ProcessedTask } from '../types';

interface GanttChartProps {
  tasks: ProcessedTask[];
  baselineTasks?: ProcessedTask[]; // Ghost main
  baselineRealisticTasks?: ProcessedTask[]; // Ghost realistic
  baselineMaxVelocityTasks?: ProcessedTask[]; // Ghost max velocity
  realisticTasks?: ProcessedTask[];
  maxVelocityTasks?: ProcessedTask[];
  weekendHours: number;
  isDarkMode?: boolean;
  isPdfExport?: boolean;
  bufferPercent?: number;
  projectStartDate: Date;
  currentDate?: Date;
  onTaskToggle?: (taskId: string) => void;
  isExecutionMode?: boolean;
}

export const GanttChart: React.FC<GanttChartProps> = ({ 
  tasks, 
  baselineTasks,
  baselineRealisticTasks,
  baselineMaxVelocityTasks,
  realisticTasks, 
  maxVelocityTasks, 
  weekendHours, 
  isDarkMode = false,
  isPdfExport = false,
  bufferPercent = 30,
  projectStartDate,
  currentDate,
  onTaskToggle,
  isExecutionMode = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Tooltip State for Fixed Positioning (Solves Z-Index clipping)
  const [activeTooltip, setActiveTooltip] = useState<{
    x: number;
    y: number;
    task: ProcessedTask;
    realistic?: ProcessedTask;
  } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 640);

    // Check on mount
    if (typeof window !== 'undefined') {
        checkMobile();
        window.addEventListener('resize', checkMobile);
    }
    return () => {
        if (typeof window !== 'undefined') window.removeEventListener('resize', checkMobile);
    }
  }, []);

  // Metrics for rendering - Condensed if exporting to PDF or on Mobile
  const DAY_WIDTH = isPdfExport ? 25 : (isMobile ? 40 : 60);
  const HEADER_HEIGHT = 54;
  const ROW_HEIGHT = 52; 
  // Reduced sidebar width slightly since we are truncating names
  const SIDEBAR_WIDTH = isPdfExport ? 140 : (isMobile ? 50 : 200); 

  // VISUAL ADJUSTMENT: Start the chart 1 day before the actual Project Start Date
  const VISUAL_SHIFT_DAYS = 1;

  // Helper to find the max day extent across a set of tasks
  const getEndDay = (taskList?: ProcessedTask[]) => 
    taskList ? taskList.reduce((acc, t) => Math.max(acc, t.startOffsetDays + t.durationDays), 0) : 0;

  // Calculate total days including all possible scenarios (Ghosts, Realistic, Max Vel)
  const effectiveMaxDay = Math.max(
      getEndDay(tasks),
      getEndDay(realisticTasks),
      getEndDay(baselineTasks),
      getEndDay(baselineRealisticTasks),
      getEndDay(maxVelocityTasks),
      getEndDay(baselineMaxVelocityTasks)
  );

  const totalDays = effectiveMaxDay + 4 + VISUAL_SHIFT_DAYS; // Add ample buffer + shift
  const chartWidth = totalDays * DAY_WIDTH;
  const totalWidth = SIDEBAR_WIDTH + chartWidth;

  // Calculate Today's position using passed currentDate or default to now
  const now = currentDate || new Date();
  const diffTime = now.getTime() - projectStartDate.getTime();
  const nowOffsetDays = (diffTime / (1000 * 60 * 60 * 24)) + VISUAL_SHIFT_DAYS;
  const showNowLine = nowOffsetDays >= 0 && nowOffsetDays <= totalDays;

  // Helper to format render dates
  const getDateLabel = (dayOffset: number) => {
    // Use the projectStartDate as the anchor
    const d = new Date(projectStartDate);
    d.setDate(d.getDate() + dayOffset - VISUAL_SHIFT_DAYS);
    return {
      weekday: d.toLocaleDateString('en-US', { weekday: 'short' }),
      day: d.getDate(),
      month: d.toLocaleDateString('en-US', { month: 'short' }),
      isWeekend: d.getDay() === 0 || d.getDay() === 6
    };
  };

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-500 border-purple-600';
    if (phase.includes('Frontend')) return 'bg-blue-500 border-blue-600';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-500 border-indigo-600';
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-500 border-rose-600';
    if (phase.includes('Deployment')) return 'bg-emerald-500 border-emerald-600';
    if (phase.includes('User')) return 'bg-amber-500 border-amber-600';
    return isDarkMode ? 'bg-slate-600 border-slate-700' : 'bg-slate-500 border-slate-600';
  };

  return (
    <div className={`gantt-container bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col ${isExecutionMode ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4">
        <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 whitespace-nowrap">Timeline & Dependencies</h3>
            {isExecutionMode && (
                <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-sm uppercase tracking-wider animate-pulse">
                    Execution Mode
                </span>
            )}
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs w-full xl:w-auto xl:justify-end">
           {/* Schedule Types */}
           <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-4 mr-2">
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-emerald-500 rounded-sm"></span> Realistic ({bufferPercent}% Buffer)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-rose-500 rounded-sm"></span> Max Velocity (10h/5h)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-black dark:bg-slate-200 rounded-sm"></span> Done
                </div>
           </div>

           {/* Phase Legend */}
           <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-purple-500 rounded-sm"></span> Design
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></span> Frontend
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-indigo-500 rounded-sm"></span> Logic
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-rose-500 rounded-sm"></span> QA
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm"></span> Deploy
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-amber-500 rounded-sm"></span> Outreach
                </div>
           </div>
        </div>
      </div>

      <div className="gantt-scroll-area overflow-x-auto" ref={containerRef}>
        <div 
            className="flex relative" 
            style={{ 
                width: totalWidth,
                height: (tasks.length * ROW_HEIGHT) + HEADER_HEIGHT + 20 
            }}
        >
            {/* Left Column: Task Names (Frozen/Sticky) */}
            <div 
              style={{ width: SIDEBAR_WIDTH }}
              className="sticky left-0 flex-shrink-0 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-30 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_12px_-4px_rgba(0,0,0,0.3)] transition-all duration-300"
            >
            <div style={{ height: HEADER_HEIGHT }} className={`sticky top-0 z-40 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 p-2 font-bold text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center ${isMobile ? 'justify-center' : ''}`}>
                {isMobile ? '#' : 'Task Name'}
            </div>
            {tasks.map((task) => {
                // Shorten task name to 3 words
                const words = task.task_name.split(' ');
                const shortName = words.slice(0, 3).join(' ') + (words.length > 3 ? '...' : '');

                // Dependency Logic: Lock if not completed AND has unfinished predecessors
                const hasUnfinishedPredecessors = task.predecessors.some(predId => {
                    const pred = tasks.find(t => t.id === predId);
                    return pred && !pred.isCompleted;
                });

                const isDependencyLocked = !task.isCompleted && hasUnfinishedPredecessors;

                // Visual dimming for text when in Execution Mode
                const textOpacityClass = isExecutionMode && !task.isCompleted ? 'opacity-80' : '';

                return (
                    <div 
                    key={task.id} 
                    style={{ height: ROW_HEIGHT }} 
                    className={`border-b border-slate-100 dark:border-slate-800 px-3 flex items-center text-xs font-medium text-slate-700 dark:text-slate-300 ${isMobile ? 'justify-center' : ''}`}
                    title={task.task_name}
                    >
                        <div className="flex items-center w-full min-w-0">
                            {/* Circular ID Badge (Acts as the Done Button) */}
                            <div 
                                onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                className={`
                                    flex items-center justify-center w-6 h-6 rounded-full border text-[10px] font-bold transition-all duration-200 flex-shrink-0 mr-2 z-10 relative
                                    ${task.isCompleted 
                                        ? 'bg-black dark:bg-slate-200 text-white dark:text-slate-900 border-black dark:border-slate-200 ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' 
                                        : isDependencyLocked
                                            ? 'bg-slate-100 text-slate-300 border-slate-200 dark:bg-slate-800 dark:text-slate-600 dark:border-slate-700 cursor-not-allowed'
                                            : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-300 dark:border-slate-600 hover:border-indigo-500 hover:text-indigo-600 cursor-pointer'
                                    }
                                    ${isExecutionMode && !task.isCompleted && !isDependencyLocked ? 'animate-pulse ring-1 ring-indigo-500/50' : ''}
                                `}
                                title={isDependencyLocked ? "Complete predecessors first" : "Click to toggle status"}
                            >
                                {task.isCompleted ? (
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                        <path fillRule="evenodd" d="M19.916 4.626a.75.75 0 01.208 1.04l-9 13.5a.75.75 0 01-1.154.114l-6-6a.75.75 0 011.06-1.06l5.353 5.353 8.493-12.739a.75.75 0 011.04-.208z" clipRule="evenodd" />
                                    </svg>
                                ) : (
                                    task.id
                                )}
                            </div>

                            {!isMobile && (
                                <span className={`truncate transition-opacity ${task.isCompleted ? 'text-slate-400 line-through' : (isDependencyLocked ? 'text-slate-400 dark:text-slate-600' : textOpacityClass)}`}>
                                    {shortName}
                                </span>
                            )}
                        </div>
                    </div>
                );
            })}
            </div>

            {/* Right Column: Chart Area */}
            <div className="flex-1 relative h-full">

                {/* Timeline Header (Sticky Top) */}
                <div className="flex sticky top-0 left-0 right-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 z-20" style={{ height: HEADER_HEIGHT }}>
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { day, month, weekday, isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 flex flex-col items-center justify-center text-[10px] border-r border-slate-200 dark:border-slate-800 leading-tight ${
                            isZeroWorkWeekend ? 'bg-slate-200 dark:bg-slate-950 text-slate-400 dark:text-slate-600' : 
                            isWeekend ? 'bg-slate-100 dark:bg-slate-900' : ''
                        }`}
                    >
                        <span className="text-[9px] uppercase font-bold text-slate-500 dark:text-slate-400">{weekday}</span>
                        <span className="font-bold text-slate-800 dark:text-slate-200 text-xs">{day}</span>
                        <span className="text-[9px] text-slate-400 dark:text-slate-500">{month}</span>
                    </div>
                    );
                })}
                </div>

                {/* Grid Background */}
                <div className="absolute top-0 bottom-0 left-0 right-0 z-0 flex pointer-events-none">
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 border-r border-dashed border-slate-300 dark:border-slate-800 h-full ${
                            isZeroWorkWeekend ? 'bg-slate-100 dark:bg-slate-950/50' : 
                            isWeekend ? 'bg-slate-50/50 dark:bg-slate-900/30' : ''
                        }`}
                    />
                    );
                })}
                </div>

                {/* Current Date Line */}
                {showNowLine && (
                    <div 
                        className="absolute bottom-0 border-l-2 border-dashed border-amber-500 z-50 pointer-events-none"
                        style={{ 
                            left: Math.max(nowOffsetDays * DAY_WIDTH, 0),
                            top: HEADER_HEIGHT, 
                        }}
                    >
                        <div 
                            className="absolute -top-3 text-[9px] font-bold text-white bg-amber-600 dark:bg-amber-500 px-2 py-1 rounded shadow-md whitespace-nowrap ring-2 ring-white dark:ring-slate-900 z-50 transition-transform duration-300"
                            style={{
                                left: 0,
                                transform: nowOffsetDays * DAY_WIDTH < 25 ? 'none' : 'translateX(-50%)'
                            }}
                        >
                            Today
                        </div>
                    </div>
                )}

                {/* Dependency Lines (SVG Layer) */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ marginTop: HEADER_HEIGHT }}>
                <defs>
                    <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                    <polygon points="0 0, 6 2, 0 4" fill={isDarkMode ? "#64748b" : "#94a3b8"} />
                    </marker>
                </defs>
                {tasks.map(task => 
                    task.predecessors.map(predId => {
                    const pred = tasks.find(p => p.id === predId);
                    if (!pred) return null;

                    // Coordinates
                    // We target the center of the main bar (top: 16, height: 20 -> center 26)
                    // SHIFT: Add VISUAL_SHIFT_DAYS to offsets
                    const startX = (pred.startOffsetDays + pred.durationDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const startY = (pred.rowIndex * ROW_HEIGHT) + 26; 
                    const endX = (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const endY = (task.rowIndex * ROW_HEIGHT) + 26;

                    // Curve logic
                    const gap = endX - startX;
                    const midX = startX + (gap > 20 ? 15 : gap/2);

                    return (
                        <path
                        key={`${pred.id}-${task.id}`}
                        d={`M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${endY} L ${endX} ${endY}`}
                        fill="none"
                        stroke={isDarkMode ? "#64748b" : "#94a3b8"}
                        strokeWidth="1.5"
                        strokeDasharray="3 3"
                        markerEnd="url(#arrowhead)"
                        className="transition-all duration-300 opacity-50"
                        />
                    );
                    })
                )}
                </svg>

                {/* Task Bars */}
                <div className="absolute top-0 left-0 w-full z-10" style={{ marginTop: HEADER_HEIGHT }}>
                {tasks.map((task) => {
                    // Find corresponding realistic task
                    const realistic = realisticTasks?.find(t => t.id === task.id);
                    // Find corresponding max velocity task
                    const maxVel = maxVelocityTasks?.find(t => t.id === task.id);

                    // Find corresponding baseline task (Ghost Main)
                    const baseline = baselineTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline realistic (Ghost Realistic)
                    const baselineRealistic = baselineRealisticTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline max velocity (Ghost Max Vel - Immutable)
                    const baselineMaxVel = baselineMaxVelocityTasks?.find(t => t.id === task.id);

                    const isDone = task.isCompleted;

                    return (
                        <div
                        key={task.id}
                        style={{
                            height: ROW_HEIGHT,
                            width: '100%',
                            position: 'relative'
                        }}
                        >
                        {/* 1. Ghost Realistic Bar (Green Dashed) - Top symmetric (6px) */}
                        {baselineRealistic && (
                            <div
                                className="absolute rounded-sm border border-emerald-300 dark:border-emerald-700/50 bg-emerald-100/30 dark:bg-emerald-900/10 pointer-events-none"
                                style={{
                                    left: (baselineRealistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineRealistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6, 
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 2. Ghost Max Velocity Bar (Red Dashed) - Bottom symmetric (42px) */}
                        {baselineMaxVel && (
                             <div
                                className="absolute rounded-sm border border-rose-300 dark:border-rose-700/50 bg-rose-100/30 dark:bg-rose-900/10 pointer-events-none"
                                style={{
                                    left: (baselineMaxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineMaxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 3. Ghost Main Bar (Gray Dashed) - Center symmetric (19px) */}
                        {baseline && (
                             <div
                                className="absolute rounded-sm bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 pointer-events-none"
                                style={{
                                    left: (baseline.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baseline.durationDays * DAY_WIDTH, 4),
                                    height: 14,
                                    top: 19,
                                    opacity: 0.5,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 4. Live Max Velocity Bar (Red Solid) - Bottom symmetric (42px) */}
                        {!isDone && maxVel && (
                             <div
                                className="absolute rounded-sm bg-rose-400/80 dark:bg-rose-500/80 pointer-events-none z-10"
                                style={{
                                    left: (maxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(maxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                }}
                            />
                        )}

                         {/* 5. Live Realistic Bar (Green Solid) - Top symmetric (6px) */}
                         {!isDone && realistic && (
                             <div
                                className="absolute rounded-sm bg-emerald-400/80 dark:bg-emerald-500/80 pointer-events-none z-10"
                                style={{
                                    left: (realistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(realistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6,
                                }}
                            />
                        )}

                        {/* 6. MAIN TASK BAR - Center (16px) */}
                        <div
                            className={`absolute rounded shadow-sm border flex items-center justify-center z-20 group cursor-help transition-all duration-300 ${
                                isDone 
                                ? 'bg-black dark:bg-slate-200 border-black dark:border-slate-200' 
                                : getPhaseColor(task.phase)
                            }`}
                            style={{
                                left: (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                width: Math.max(task.durationDays * DAY_WIDTH, 4),
                                height: 20,
                                top: 16,
                            }}
                            onMouseEnter={(e) => {
                                const rect = e.currentTarget.getBoundingClientRect();
                                setActiveTooltip({
                                    x: rect.left + (rect.width / 2),
                                    y: rect.top,
                                    task,
                                    realistic
                                });
                            }}
                            onMouseLeave={() => setActiveTooltip(null)}
                        >
                             {/* Label inside bar if wide enough */}
                             {(task.durationDays * DAY_WIDTH) > 60 && (
                                <span className={`text-[9px] font-bold truncate px-2 ${isDone ? 'text-white dark:text-slate-900' : 'text-white'}`}>
                                    {isDone ? 'DONE' : `${task.duration_hours}h`}
                                </span>
                             )}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* PORTALED TOOLTIP OVERLAY */}
      {activeTooltip && typeof document !== 'undefined' && createPortal(
            <div 
                className="fixed z-[9999] pointer-events-none print:hidden"
                style={{ 
                    left: activeTooltip.x, 
                    top: activeTooltip.y,
                    transform: 'translate(-50%, -100%)',
                    marginTop: '-8px'
                }}
            >
                <div className="bg-slate-900 text-white text-xs rounded-lg p-3 shadow-xl w-48 border border-slate-700">
                    <div className="font-bold mb-1">{activeTooltip.task.task_name}</div>
                    <div className="text-slate-400 mb-2">{activeTooltip.task.phase}</div>
                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                            <span className="block text-slate-500">Start</span>
                            {activeTooltip.task.startDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">End</span>
                            {activeTooltip.task.endDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">Duration</span>
                            {activeTooltip.task.duration_hours}h
                        </div>
                        {!activeTooltip.task.isCompleted && activeTooltip.realistic && (
                            <div>
                                <span className="block text-emerald-400">Realistic End</span>
                                {activeTooltip.realistic.endDate.toLocaleDateString()}
                            </div>
                        )}
                    </div>
                </div>
                {/* Triangle */}
                <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900 mx-auto"></div>
            </div>,
            document.body
       )}
    </div>
  );
};

import React, { useState } from 'react';
import { ProcessedTask } from '../types';

interface ProjectTableProps {
  tasks: ProcessedTask[];
  onTaskToggle?: (taskId: string) => void;
}

export const ProjectTable: React.FC<ProjectTableProps> = ({ tasks, onTaskToggle }) => {
  const [isOpen, setIsOpen] = useState(false);
  const totalHours = tasks.reduce((sum, t) => sum + t.duration_hours, 0);

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-100 text-purple-800 border-purple-200 dark:bg-purple-900/30 dark:text-purple-300 dark:border-purple-800';
    if (phase.includes('Frontend')) return 'bg-blue-100 text-blue-800 border-blue-200 dark:bg-blue-900/30 dark:text-blue-300 dark:border-blue-800';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-100 text-indigo-800 border-indigo-200 dark:bg-indigo-900/30 dark:text-indigo-300 dark:border-indigo-800';
    // Swapped QA and User
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-100 text-rose-800 border-rose-200 dark:bg-rose-900/30 dark:text-rose-300 dark:border-rose-800';
    if (phase.includes('Deployment')) return 'bg-emerald-100 text-emerald-800 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-800';
    if (phase.includes('User')) return 'bg-amber-100 text-amber-800 border-amber-200 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-800';
    return 'bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:border-slate-700';
  };

  const formatDate = (date: Date) => {
    return date.toLocaleString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      hour12: true
    });
  };

  const formatCompletionDate = (isoStr?: string) => {
      if (!isoStr) return null;
      const d = new Date(isoStr);
      return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden transition-all duration-300">
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full px-6 py-4 bg-slate-50 dark:bg-slate-800/50 flex justify-between items-center hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer outline-none ${isOpen ? 'border-b border-slate-200 dark:border-slate-800' : ''}`}
      >
        <div className="flex items-center gap-3">
            {/* Added a subtle list icon to replace the chevron on the left, for aesthetics */}
            <div className="text-slate-400 dark:text-slate-500">
               <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                  <path fillRule="evenodd" d="M2.625 6.75a1.125 1.125 0 112.25 0 1.125 1.125 0 01-2.25 0zm4.875 0A.75.75 0 018.25 6h12a.75.75 0 010 1.5h-12a.75.75 0 01-.75-.75zM2.625 12a1.125 1.125 0 112.25 0 1.125 1.125 0 01-2.25 0zM7.5 12a.75.75 0 01.75-.75h12a.75.75 0 010 1.5h-12A.75.75 0 017.5 12zm-4.875 5.25a1.125 1.125 0 112.25 0 1.125 1.125 0 01-2.25 0zm4.875 0a.75.75 0 01.75-.75h12a.75.75 0 010 1.5h-12a.75.75 0 01-.75-.75z" clipRule="evenodd" />
               </svg>
            </div>
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100">Detailed Workload Breakdown</h3>
        </div>

        <div className="flex items-center gap-4">
            <span className="text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
            {tasks.length} Tasks Defined
            </span>
            <div className={`text-slate-500 dark:text-slate-400 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}>
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" clipRule="evenodd" />
                </svg>
            </div>
        </div>
      </button>

      {isOpen && (
        <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-slate-200 dark:divide-slate-800">
            <thead className="bg-slate-50 dark:bg-slate-800/50">
                <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider w-12">
                    ID
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                    Task & Phase
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider w-1/4">
                    Workload
                </th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                    Schedule
                </th>
                </tr>
            </thead>
            <tbody className="bg-white dark:bg-slate-900 divide-y divide-slate-200 dark:divide-slate-800">
                {tasks.map((task) => {
                const percentage = Math.round((task.duration_hours / totalHours) * 100);

                // Calculate dependency lock for table view
                const isLocked = !task.isCompleted && task.predecessors.some(pId => {
                    const p = tasks.find(t => t.id === pId);
                    return p && !p.isCompleted;
                });

                return (
                    <tr key={task.id} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                    <td 
                        onClick={() => !isLocked && onTaskToggle && onTaskToggle(task.id)}
                        className={`px-6 py-4 whitespace-nowrap align-top`}
                        title={isLocked ? "Complete predecessors first" : "Click to toggle completion"}
                    >
                         <div className={`
                            flex items-center justify-center w-6 h-6 rounded-full border text-[10px] font-bold transition-all duration-200 cursor-pointer
                            ${task.isCompleted 
                                ? 'bg-black dark:bg-slate-200 text-white dark:text-slate-900 border-black dark:border-slate-200 ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' 
                                : isLocked
                                    ? 'bg-slate-100 text-slate-300 border-slate-200 dark:bg-slate-800 dark:text-slate-600 dark:border-slate-700 cursor-not-allowed'
                                    : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-300 dark:border-slate-600 hover:border-indigo-500 hover:text-indigo-600'
                            }
                        `}>
                            {task.isCompleted ? (
                                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                    <path fillRule="evenodd" d="M19.916 4.626a.75.75 0 01.208 1.04l-9 13.5a.75.75 0 01-1.154.114l-6-6a.75.75 0 011.06-1.06l5.353 5.353 8.493-12.739a.75.75 0 011.04-.208z" clipRule="evenodd" />
                                </svg>
                            ) : (
                                task.id
                            )}
                        </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-700 dark:text-slate-300 align-top">
                        <div className="font-bold text-slate-800 dark:text-slate-100 mb-1">{task.task_name}</div>
                        <span className={`px-2 py-0.5 inline-flex text-[10px] leading-4 font-semibold rounded-full border ${getPhaseColor(task.phase)}`}>
                        {task.phase}
                        </span>
                        <div className="mt-2 text-xs text-slate-400 dark:text-slate-500">
                        Deps: {task.predecessors.length > 0 ? task.predecessors.join(', ') : 'None'}
                        </div>
                        {task.completionDate && task.isCompleted && (
                            <div className="mt-1 text-xs text-emerald-600 dark:text-emerald-400 font-medium">
                                ✓ Done: {formatCompletionDate(task.completionDate)}
                            </div>
                        )}
                    </td>
                    <td className="px-6 py-4 align-top">
                        <div className="w-full max-w-xs">
                            <div className="flex justify-between items-baseline mb-1">
                                <span className="text-sm font-bold text-slate-700 dark:text-slate-200">{task.duration_hours}h</span>
                                <span className="text-xs text-slate-500 dark:text-slate-400">{percentage}% of total</span>
                            </div>
                            <div className="w-full bg-slate-100 dark:bg-slate-800 rounded-full h-2.5 overflow-hidden">
                                <div 
                                    className="bg-indigo-500 h-2.5 rounded-full" 
                                    style={{ width: `${Math.max(percentage, 5)}%` }}
                                ></div>
                            </div>
                        </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-xs text-slate-600 dark:text-slate-400 align-top">
                        <div className="flex flex-col gap-1">
                            <div className="flex items-center gap-2">
                                <span className="w-8 text-slate-400 dark:text-slate-500 uppercase text-[10px] font-bold">Start</span>
                                <span className="font-mono">{formatDate(task.startDate)}</span>
                            </div>
                            <div className="flex items-center gap-2">
                                <span className="w-8 text-slate-400 dark:text-slate-500 uppercase text-[10px] font-bold">End</span>
                                <span className="font-mono">{formatDate(task.endDate)}</span>
                            </div>
                        </div>
                    </td>
                    </tr>
                );
                })}
            </tbody>
            </table>
        </div>
      )}
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { ProcessedTask } from '../types';

interface GanttChartProps {
  tasks: ProcessedTask[];
  baselineTasks?: ProcessedTask[]; // Ghost main
  baselineRealisticTasks?: ProcessedTask[]; // Ghost realistic
  baselineMaxVelocityTasks?: ProcessedTask[]; // Ghost max velocity
  realisticTasks?: ProcessedTask[];
  maxVelocityTasks?: ProcessedTask[];
  weekendHours: number;
  isDarkMode?: boolean;
  isPdfExport?: boolean;
  bufferPercent?: number;
  projectStartDate: Date;
  currentDate?: Date;
  onTaskToggle?: (taskId: string) => void;
  isExecutionMode?: boolean;
}

export const GanttChart: React.FC<GanttChartProps> = ({ 
  tasks, 
  baselineTasks,
  baselineRealisticTasks,
  baselineMaxVelocityTasks,
  realisticTasks, 
  maxVelocityTasks, 
  weekendHours, 
  isDarkMode = false,
  isPdfExport = false,
  bufferPercent = 30,
  projectStartDate,
  currentDate,
  onTaskToggle,
  isExecutionMode = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Tooltip State for Fixed Positioning (Solves Z-Index clipping)
  const [activeTooltip, setActiveTooltip] = useState<{
    x: number;
    y: number;
    task: ProcessedTask;
    realistic?: ProcessedTask;
  } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 640);

    // Check on mount
    if (typeof window !== 'undefined') {
        checkMobile();
        window.addEventListener('resize', checkMobile);
    }
    return () => {
        if (typeof window !== 'undefined') window.removeEventListener('resize', checkMobile);
    }
  }, []);

  // Metrics for rendering - Condensed if exporting to PDF or on Mobile
  const DAY_WIDTH = isPdfExport ? 25 : (isMobile ? 40 : 60);
  const HEADER_HEIGHT = 54;
  const ROW_HEIGHT = 52; 
  // Reduced sidebar width slightly since we are truncating names
  const SIDEBAR_WIDTH = isPdfExport ? 140 : (isMobile ? 50 : 200); 

  // VISUAL ADJUSTMENT: Start the chart 1 day before the actual Project Start Date
  const VISUAL_SHIFT_DAYS = 1;

  // Helper to find the max day extent across a set of tasks
  const getEndDay = (taskList?: ProcessedTask[]) => 
    taskList ? taskList.reduce((acc, t) => Math.max(acc, t.startOffsetDays + t.durationDays), 0) : 0;

  // Calculate total days including all possible scenarios (Ghosts, Realistic, Max Vel)
  const effectiveMaxDay = Math.max(
      getEndDay(tasks),
      getEndDay(realisticTasks),
      getEndDay(baselineTasks),
      getEndDay(baselineRealisticTasks),
      getEndDay(maxVelocityTasks),
      getEndDay(baselineMaxVelocityTasks)
  );

  const totalDays = effectiveMaxDay + 4 + VISUAL_SHIFT_DAYS; // Add ample buffer + shift
  const chartWidth = totalDays * DAY_WIDTH;
  const totalWidth = SIDEBAR_WIDTH + chartWidth;

  // Calculate Today's position using passed currentDate or default to now
  const now = currentDate || new Date();
  const diffTime = now.getTime() - projectStartDate.getTime();
  const nowOffsetDays = (diffTime / (1000 * 60 * 60 * 24)) + VISUAL_SHIFT_DAYS;
  const showNowLine = nowOffsetDays >= 0 && nowOffsetDays <= totalDays;

  // Helper to format render dates
  const getDateLabel = (dayOffset: number) => {
    // Use the projectStartDate as the anchor
    const d = new Date(projectStartDate);
    d.setDate(d.getDate() + dayOffset - VISUAL_SHIFT_DAYS);
    return {
      weekday: d.toLocaleDateString('en-US', { weekday: 'short' }),
      day: d.getDate(),
      month: d.toLocaleDateString('en-US', { month: 'short' }),
      isWeekend: d.getDay() === 0 || d.getDay() === 6
    };
  };

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-500 border-purple-600';
    if (phase.includes('Frontend')) return 'bg-blue-500 border-blue-600';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-500 border-indigo-600';
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-500 border-rose-600';
    if (phase.includes('Deployment')) return 'bg-emerald-500 border-emerald-600';
    if (phase.includes('User')) return 'bg-amber-500 border-amber-600';
    return isDarkMode ? 'bg-slate-600 border-slate-700' : 'bg-slate-500 border-slate-600';
  };

  return (
    <div className={`gantt-container bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col ${isExecutionMode ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4">
        <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 whitespace-nowrap">Timeline & Dependencies</h3>
            {isExecutionMode && (
                <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-sm uppercase tracking-wider animate-pulse">
                    Execution Mode
                </span>
            )}
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs w-full xl:w-auto xl:justify-end">
           {/* Schedule Types */}
           <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-4 mr-2">
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-emerald-500 rounded-sm"></span> Realistic ({bufferPercent}% Buffer)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-rose-500 rounded-sm"></span> Max Velocity (10h/5h)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-black dark:bg-slate-200 rounded-sm"></span> Done
                </div>
           </div>

           {/* Phase Legend */}
           <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-purple-500 rounded-sm"></span> Design
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></span> Frontend
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-indigo-500 rounded-sm"></span> Logic
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-rose-500 rounded-sm"></span> QA
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm"></span> Deploy
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-amber-500 rounded-sm"></span> Outreach
                </div>
           </div>
        </div>
      </div>

      <div className="gantt-scroll-area overflow-x-auto" ref={containerRef}>
        <div 
            className="flex relative" 
            style={{ 
                width: totalWidth,
                height: (tasks.length * ROW_HEIGHT) + HEADER_HEIGHT + 20 
            }}
        >
            {/* Left Column: Task Names (Frozen/Sticky) */}
            <div 
              style={{ width: SIDEBAR_WIDTH }}
              className="sticky left-0 flex-shrink-0 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-30 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_12px_-4px_rgba(0,0,0,0.3)] transition-all duration-300"
            >
            <div style={{ height: HEADER_HEIGHT }} className={`sticky top-0 z-40 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 p-2 font-bold text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center ${isMobile ? 'justify-center' : ''}`}>
                {isMobile ? '#' : 'Task Name'}
            </div>
            {tasks.map((task) => {
                // Shorten task name to 3 words
                const words = task.task_name.split(' ');
                const shortName = words.slice(0, 3).join(' ') + (words.length > 3 ? '...' : '');

                // Dependency Logic: Lock if not completed AND has unfinished predecessors
                const hasUnfinishedPredecessors = task.predecessors.some(predId => {
                    const pred = tasks.find(t => t.id === predId);
                    return pred && !pred.isCompleted;
                });

                const isDependencyLocked = !task.isCompleted && hasUnfinishedPredecessors;

                // Visual dimming for text when in Execution Mode
                const textOpacityClass = isExecutionMode && !task.isCompleted ? 'opacity-80' : '';

                return (
                    <div 
                    key={task.id} 
                    style={{ height: ROW_HEIGHT }} 
                    className={`border-b border-slate-100 dark:border-slate-800 px-3 flex items-center text-xs font-medium text-slate-700 dark:text-slate-300 ${isMobile ? 'justify-center' : ''}`}
                    title={task.task_name}
                    >
                        <div className="flex items-center w-full min-w-0">
                            {/* Circular ID Badge (Acts as the Done Button) */}
                            <div 
                                onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                className={`
                                    flex items-center justify-center w-6 h-6 rounded-full border text-[10px] font-bold transition-all duration-200 flex-shrink-0 mr-2 z-10 relative
                                    ${task.isCompleted 
                                        ? 'bg-black dark:bg-slate-200 text-white dark:text-slate-900 border-black dark:border-slate-200 ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' 
                                        : isDependencyLocked
                                            ? 'bg-slate-100 text-slate-300 border-slate-200 dark:bg-slate-800 dark:text-slate-600 dark:border-slate-700 cursor-not-allowed'
                                            : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-300 dark:border-slate-600 hover:border-indigo-500 hover:text-indigo-600 cursor-pointer'
                                    }
                                    ${isExecutionMode && !task.isCompleted && !isDependencyLocked ? 'animate-pulse ring-1 ring-indigo-500/50' : ''}
                                `}
                                title={isDependencyLocked ? "Complete predecessors first" : "Click to toggle status"}
                            >
                                {task.isCompleted ? (
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                        <path fillRule="evenodd" d="M19.916 4.626a.75.75 0 01.208 1.04l-9 13.5a.75.75 0 01-1.154.114l-6-6a.75.75 0 011.06-1.06l5.353 5.353 8.493-12.739a.75.75 0 011.04-.208z" clipRule="evenodd" />
                                    </svg>
                                ) : (
                                    task.id
                                )}
                            </div>

                            {!isMobile && (
                                <span className={`truncate transition-opacity ${task.isCompleted ? 'text-slate-400 line-through' : (isDependencyLocked ? 'text-slate-400 dark:text-slate-600' : textOpacityClass)}`}>
                                    {shortName}
                                </span>
                            )}
                        </div>
                    </div>
                );
            })}
            </div>

            {/* Right Column: Chart Area */}
            <div className="flex-1 relative h-full">

                {/* Timeline Header (Sticky Top) */}
                <div className="flex sticky top-0 left-0 right-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 z-20" style={{ height: HEADER_HEIGHT }}>
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { day, month, weekday, isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 flex flex-col items-center justify-center text-[10px] border-r border-slate-200 dark:border-slate-800 leading-tight ${
                            isZeroWorkWeekend ? 'bg-slate-200 dark:bg-slate-950 text-slate-400 dark:text-slate-600' : 
                            isWeekend ? 'bg-slate-100 dark:bg-slate-900' : ''
                        }`}
                    >
                        <span className="text-[9px] uppercase font-bold text-slate-500 dark:text-slate-400">{weekday}</span>
                        <span className="font-bold text-slate-800 dark:text-slate-200 text-xs">{day}</span>
                        <span className="text-[9px] text-slate-400 dark:text-slate-500">{month}</span>
                    </div>
                    );
                })}
                </div>

                {/* Grid Background */}
                <div className="absolute top-0 bottom-0 left-0 right-0 z-0 flex pointer-events-none">
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 border-r border-dashed border-slate-300 dark:border-slate-800 h-full ${
                            isZeroWorkWeekend ? 'bg-slate-100 dark:bg-slate-950/50' : 
                            isWeekend ? 'bg-slate-50/50 dark:bg-slate-900/30' : ''
                        }`}
                    />
                    );
                })}
                </div>

                {/* Current Date Line */}
                {showNowLine && (
                    <div 
                        className="absolute bottom-0 border-l-2 border-dashed border-amber-500 z-50 pointer-events-none"
                        style={{ 
                            left: Math.max(nowOffsetDays * DAY_WIDTH, 0),
                            top: HEADER_HEIGHT, 
                        }}
                    >
                        <div 
                            className="absolute -top-3 text-[9px] font-bold text-white bg-amber-600 dark:bg-amber-500 px-2 py-1 rounded shadow-md whitespace-nowrap ring-2 ring-white dark:ring-slate-900 z-50 transition-transform duration-300"
                            style={{
                                left: 0,
                                transform: nowOffsetDays * DAY_WIDTH < 25 ? 'none' : 'translateX(-50%)'
                            }}
                        >
                            Today
                        </div>
                    </div>
                )}

                {/* Dependency Lines (SVG Layer) */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ marginTop: HEADER_HEIGHT }}>
                <defs>
                    <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                    <polygon points="0 0, 6 2, 0 4" fill={isDarkMode ? "#64748b" : "#94a3b8"} />
                    </marker>
                </defs>
                {tasks.map(task => 
                    task.predecessors.map(predId => {
                    const pred = tasks.find(p => p.id === predId);
                    if (!pred) return null;

                    // Coordinates
                    // We target the center of the main bar (top: 16, height: 20 -> center 26)
                    // SHIFT: Add VISUAL_SHIFT_DAYS to offsets
                    const startX = (pred.startOffsetDays + pred.durationDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const startY = (pred.rowIndex * ROW_HEIGHT) + 26; 
                    const endX = (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const endY = (task.rowIndex * ROW_HEIGHT) + 26;

                    // Curve logic
                    const gap = endX - startX;
                    const midX = startX + (gap > 20 ? 15 : gap/2);

                    return (
                        <path
                        key={`${pred.id}-${task.id}`}
                        d={`M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${endY} L ${endX} ${endY}`}
                        fill="none"
                        stroke={isDarkMode ? "#64748b" : "#94a3b8"}
                        strokeWidth="1.5"
                        strokeDasharray="3 3"
                        markerEnd="url(#arrowhead)"
                        className="transition-all duration-300 opacity-50"
                        />
                    );
                    })
                )}
                </svg>

                {/* Task Bars */}
                <div className="absolute top-0 left-0 w-full z-10" style={{ marginTop: HEADER_HEIGHT }}>
                {tasks.map((task) => {
                    // Find corresponding realistic task
                    const realistic = realisticTasks?.find(t => t.id === task.id);
                    // Find corresponding max velocity task
                    const maxVel = maxVelocityTasks?.find(t => t.id === task.id);

                    // Find corresponding baseline task (Ghost Main)
                    const baseline = baselineTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline realistic (Ghost Realistic)
                    const baselineRealistic = baselineRealisticTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline max velocity (Ghost Max Vel - Immutable)
                    const baselineMaxVel = baselineMaxVelocityTasks?.find(t => t.id === task.id);

                    const isDone = task.isCompleted;

                    return (
                        <div
                        key={task.id}
                        style={{
                            height: ROW_HEIGHT,
                            width: '100%',
                            position: 'relative'
                        }}
                        >
                        {/* 1. Ghost Realistic Bar (Green Dashed) - Top symmetric (6px) */}
                        {baselineRealistic && (
                            <div
                                className="absolute rounded-sm border border-emerald-300 dark:border-emerald-700/50 bg-emerald-100/30 dark:bg-emerald-900/10 pointer-events-none"
                                style={{
                                    left: (baselineRealistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineRealistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6, 
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 2. Ghost Max Velocity Bar (Red Dashed) - Bottom symmetric (42px) */}
                        {baselineMaxVel && (
                             <div
                                className="absolute rounded-sm border border-rose-300 dark:border-rose-700/50 bg-rose-100/30 dark:bg-rose-900/10 pointer-events-none"
                                style={{
                                    left: (baselineMaxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineMaxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 3. Ghost Main Bar (Gray Dashed) - Center symmetric (19px) */}
                        {baseline && (
                             <div
                                className="absolute rounded-sm bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 pointer-events-none"
                                style={{
                                    left: (baseline.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baseline.durationDays * DAY_WIDTH, 4),
                                    height: 14,
                                    top: 19,
                                    opacity: 0.5,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 4. Live Max Velocity Bar (Red Solid) - Bottom symmetric (42px) */}
                        {!isDone && maxVel && (
                             <div
                                className="absolute rounded-sm bg-rose-400/80 dark:bg-rose-500/80 pointer-events-none z-10"
                                style={{
                                    left: (maxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(maxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                }}
                            />
                        )}

                         {/* 5. Live Realistic Bar (Green Solid) - Top symmetric (6px) */}
                         {!isDone && realistic && (
                             <div
                                className="absolute rounded-sm bg-emerald-400/80 dark:bg-emerald-500/80 pointer-events-none z-10"
                                style={{
                                    left: (realistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(realistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6,
                                }}
                            />
                        )}

                        {/* 6. MAIN TASK BAR - Center (16px) */}
                        <div
                            className={`absolute rounded shadow-sm border flex items-center justify-center z-20 group cursor-help transition-all duration-300 ${
                                getPhaseColor(task.phase)
                            } ${isDone ? 'opacity-75 saturate-75' : ''}`}
                            style={{
                                left: (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                width: Math.max(task.durationDays * DAY_WIDTH, 4),
                                height: 20,
                                top: 16,
                            }}
                            onMouseEnter={(e) => {
                                const rect = e.currentTarget.getBoundingClientRect();
                                setActiveTooltip({
                                    x: rect.left + (rect.width / 2),
                                    y: rect.top,
                                    task,
                                    realistic
                                });
                            }}
                            onMouseLeave={() => setActiveTooltip(null)}
                        >
                             {/* Black Strikethrough Line for Done state */}
                             {isDone && (
                                <div className="absolute w-full h-[2px] bg-slate-950 dark:bg-white z-30 pointer-events-none" />
                             )}

                             {/* Label inside bar if wide enough */}
                             {(task.durationDays * DAY_WIDTH) > 60 && (
                                <span className="text-[9px] font-bold truncate px-2 text-white z-20 relative">
                                    {isDone ? 'DONE' : `${task.duration_hours}h`}
                                </span>
                             )}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* PORTALED TOOLTIP OVERLAY */}
      {activeTooltip && typeof document !== 'undefined' && createPortal(
            <div 
                className="fixed z-[9999] pointer-events-none print:hidden"
                style={{ 
                    left: activeTooltip.x, 
                    top: activeTooltip.y,
                    transform: 'translate(-50%, -100%)',
                    marginTop: '-8px'
                }}
            >
                <div className="bg-slate-900 text-white text-xs rounded-lg p-3 shadow-xl w-48 border border-slate-700">
                    <div className="font-bold mb-1">{activeTooltip.task.task_name}</div>
                    <div className="text-slate-400 mb-2">{activeTooltip.task.phase}</div>
                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                            <span className="block text-slate-500">Start</span>
                            {activeTooltip.task.startDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">End</span>
                            {activeTooltip.task.endDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">Duration</span>
                            {activeTooltip.task.duration_hours}h
                        </div>
                        {!activeTooltip.task.isCompleted && activeTooltip.realistic && (
                            <div>
                                <span className="block text-emerald-400">Realistic End</span>
                                {activeTooltip.realistic.endDate.toLocaleDateString()}
                            </div>
                        )}
                    </div>
                </div>
                {/* Triangle */}
                <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900 mx-auto"></div>
            </div>,
            document.body
       )}
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { ProcessedTask } from '../types';

interface GanttChartProps {
  tasks: ProcessedTask[];
  baselineTasks?: ProcessedTask[]; // Ghost main
  baselineRealisticTasks?: ProcessedTask[]; // Ghost realistic
  baselineMaxVelocityTasks?: ProcessedTask[]; // Ghost max velocity
  realisticTasks?: ProcessedTask[];
  maxVelocityTasks?: ProcessedTask[];
  weekendHours: number;
  isDarkMode?: boolean;
  isPdfExport?: boolean;
  bufferPercent?: number;
  projectStartDate: Date;
  currentDate?: Date;
  onTaskToggle?: (taskId: string) => void;
  isExecutionMode?: boolean;
}

export const GanttChart: React.FC<GanttChartProps> = ({ 
  tasks, 
  baselineTasks,
  baselineRealisticTasks,
  baselineMaxVelocityTasks,
  realisticTasks, 
  maxVelocityTasks, 
  weekendHours, 
  isDarkMode = false,
  isPdfExport = false,
  bufferPercent = 30,
  projectStartDate,
  currentDate,
  onTaskToggle,
  isExecutionMode = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Tooltip State for Fixed Positioning (Solves Z-Index clipping)
  const [activeTooltip, setActiveTooltip] = useState<{
    x: number;
    y: number;
    task: ProcessedTask;
    realistic?: ProcessedTask;
  } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 640);

    // Check on mount
    if (typeof window !== 'undefined') {
        checkMobile();
        window.addEventListener('resize', checkMobile);
    }
    return () => {
        if (typeof window !== 'undefined') window.removeEventListener('resize', checkMobile);
    }
  }, []);

  // Metrics for rendering - Condensed if exporting to PDF or on Mobile
  const DAY_WIDTH = isPdfExport ? 25 : (isMobile ? 40 : 60);
  const HEADER_HEIGHT = 54;
  const ROW_HEIGHT = 52; 
  // Reduced sidebar width slightly since we are truncating names
  const SIDEBAR_WIDTH = isPdfExport ? 140 : (isMobile ? 50 : 200); 

  // VISUAL ADJUSTMENT: Start the chart 1 day before the actual Project Start Date
  const VISUAL_SHIFT_DAYS = 1;

  // Helper to find the max day extent across a set of tasks
  const getEndDay = (taskList?: ProcessedTask[]) => 
    taskList ? taskList.reduce((acc, t) => Math.max(acc, t.startOffsetDays + t.durationDays), 0) : 0;

  // Calculate total days including all possible scenarios (Ghosts, Realistic, Max Vel)
  const effectiveMaxDay = Math.max(
      getEndDay(tasks),
      getEndDay(realisticTasks),
      getEndDay(baselineTasks),
      getEndDay(baselineRealisticTasks),
      getEndDay(maxVelocityTasks),
      getEndDay(baselineMaxVelocityTasks)
  );

  const totalDays = effectiveMaxDay + 4 + VISUAL_SHIFT_DAYS; // Add ample buffer + shift
  const chartWidth = totalDays * DAY_WIDTH;
  const totalWidth = SIDEBAR_WIDTH + chartWidth;

  // Calculate Today's position using passed currentDate or default to now
  const now = currentDate || new Date();
  const diffTime = now.getTime() - projectStartDate.getTime();
  const nowOffsetDays = (diffTime / (1000 * 60 * 60 * 24)) + VISUAL_SHIFT_DAYS;
  const showNowLine = nowOffsetDays >= 0 && nowOffsetDays <= totalDays;

  // Helper to format render dates
  const getDateLabel = (dayOffset: number) => {
    // Use the projectStartDate as the anchor
    const d = new Date(projectStartDate);
    d.setDate(d.getDate() + dayOffset - VISUAL_SHIFT_DAYS);
    return {
      weekday: d.toLocaleDateString('en-US', { weekday: 'short' }),
      day: d.getDate(),
      month: d.toLocaleDateString('en-US', { month: 'short' }),
      isWeekend: d.getDay() === 0 || d.getDay() === 6
    };
  };

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-500 border-purple-600';
    if (phase.includes('Frontend')) return 'bg-blue-500 border-blue-600';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-500 border-indigo-600';
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-500 border-rose-600';
    if (phase.includes('Deployment')) return 'bg-emerald-500 border-emerald-600';
    if (phase.includes('User')) return 'bg-amber-500 border-amber-600';
    return isDarkMode ? 'bg-slate-600 border-slate-700' : 'bg-slate-500 border-slate-600';
  };

  return (
    <div className={`gantt-container bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col ${isExecutionMode ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4">
        <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 whitespace-nowrap">Timeline & Dependencies</h3>
            {isExecutionMode && (
                <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-sm uppercase tracking-wider animate-pulse">
                    Execution Mode
                </span>
            )}
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs w-full xl:w-auto xl:justify-end">
           {/* Schedule Types */}
           <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-4 mr-2">
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-emerald-500 rounded-sm"></span> Realistic ({bufferPercent}% Buffer)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-rose-500 rounded-sm"></span> Max Velocity (10h/5h)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-black dark:bg-slate-200 rounded-sm"></span> Done
                </div>
           </div>

           {/* Phase Legend */}
           <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-purple-500 rounded-sm"></span> Design
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></span> Frontend
                </div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-indigo-500 rounded-sm"></span> Logic
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-rose-500 rounded-sm"></span> QA
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm"></span> Deploy
                </div>
                 <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400">
                    <span className="w-2.5 h-2.5 bg-amber-500 rounded-sm"></span> Outreach
                </div>
           </div>
        </div>
      </div>

      <div className="gantt-scroll-area overflow-x-auto" ref={containerRef}>
        <div 
            className="flex relative" 
            style={{ 
                width: totalWidth,
                height: (tasks.length * ROW_HEIGHT) + HEADER_HEIGHT + 20 
            }}
        >
            {/* Left Column: Task Names (Frozen/Sticky) */}
            <div 
              style={{ width: SIDEBAR_WIDTH }}
              className="sticky left-0 flex-shrink-0 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-30 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_12px_-4px_rgba(0,0,0,0.3)] transition-all duration-300"
            >
            <div style={{ height: HEADER_HEIGHT }} className={`sticky top-0 z-40 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 p-2 font-bold text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center ${isMobile ? 'justify-center' : ''}`}>
                {isMobile ? '#' : 'Task Name'}
            </div>
            {tasks.map((task) => {
                // Shorten task name to 3 words
                const words = task.task_name.split(' ');
                const shortName = words.slice(0, 3).join(' ') + (words.length > 3 ? '...' : '');

                // Dependency Logic: Lock if not completed AND has unfinished predecessors
                const hasUnfinishedPredecessors = task.predecessors.some(predId => {
                    const pred = tasks.find(t => t.id === predId);
                    return pred && !pred.isCompleted;
                });

                const isDependencyLocked = !task.isCompleted && hasUnfinishedPredecessors;

                // Visual dimming for text when in Execution Mode
                const textOpacityClass = isExecutionMode && !task.isCompleted ? 'opacity-80' : '';

                return (
                    <div 
                    key={task.id} 
                    style={{ height: ROW_HEIGHT }} 
                    className={`border-b border-slate-100 dark:border-slate-800 px-3 flex items-center text-xs font-medium text-slate-700 dark:text-slate-300 ${isMobile ? 'justify-center' : ''}`}
                    title={task.task_name}
                    >
                        <div className="flex items-center w-full min-w-0">
                            {/* Circular ID Badge (Acts as the Done Button) */}
                            <div 
                                onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)}
                                className={`
                                    flex items-center justify-center w-6 h-6 rounded-full border text-[10px] font-bold transition-all duration-200 flex-shrink-0 mr-2 z-10 relative
                                    ${task.isCompleted 
                                        ? 'bg-black dark:bg-slate-200 text-white dark:text-slate-900 border-black dark:border-slate-200 ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' 
                                        : isDependencyLocked
                                            ? 'bg-slate-100 text-slate-300 border-slate-200 dark:bg-slate-800 dark:text-slate-600 dark:border-slate-700 cursor-not-allowed'
                                            : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-300 dark:border-slate-600 hover:border-indigo-500 hover:text-indigo-600 cursor-pointer'
                                    }
                                    ${isExecutionMode && !task.isCompleted && !isDependencyLocked ? 'animate-pulse ring-1 ring-indigo-500/50' : ''}
                                `}
                                title={isDependencyLocked ? "Complete predecessors first" : "Click to toggle status"}
                            >
                                {task.isCompleted ? (
                                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-3.5 h-3.5">
                                        <path fillRule="evenodd" d="M19.916 4.626a.75.75 0 01.208 1.04l-9 13.5a.75.75 0 01-1.154.114l-6-6a.75.75 0 011.06-1.06l5.353 5.353 8.493-12.739a.75.75 0 011.04-.208z" clipRule="evenodd" />
                                    </svg>
                                ) : (
                                    task.id
                                )}
                            </div>

                            {!isMobile && (
                                <span className={`truncate transition-opacity ${task.isCompleted ? 'text-slate-400 line-through' : (isDependencyLocked ? 'text-slate-400 dark:text-slate-600' : textOpacityClass)}`}>
                                    {shortName}
                                </span>
                            )}
                        </div>
                    </div>
                );
            })}
            </div>

            {/* Right Column: Chart Area */}
            <div className="flex-1 relative h-full">

                {/* Timeline Header (Sticky Top) */}
                <div className="flex sticky top-0 left-0 right-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 z-20" style={{ height: HEADER_HEIGHT }}>
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { day, month, weekday, isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 flex flex-col items-center justify-center text-[10px] border-r border-slate-200 dark:border-slate-800 leading-tight ${
                            isZeroWorkWeekend ? 'bg-slate-200 dark:bg-slate-950 text-slate-400 dark:text-slate-600' : 
                            isWeekend ? 'bg-slate-100 dark:bg-slate-900' : ''
                        }`}
                    >
                        <span className="text-[9px] uppercase font-bold text-slate-500 dark:text-slate-400">{weekday}</span>
                        <span className="font-bold text-slate-800 dark:text-slate-200 text-xs">{day}</span>
                        <span className="text-[9px] text-slate-400 dark:text-slate-500">{month}</span>
                    </div>
                    );
                })}
                </div>

                {/* Grid Background */}
                <div className="absolute top-0 bottom-0 left-0 right-0 z-0 flex pointer-events-none">
                {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                    const { isWeekend } = getDateLabel(i);
                    const isZeroWorkWeekend = isWeekend && weekendHours === 0;

                    return (
                    <div 
                        key={i} 
                        style={{ width: DAY_WIDTH }} 
                        className={`flex-shrink-0 border-r border-dashed border-slate-300 dark:border-slate-800 h-full ${
                            isZeroWorkWeekend ? 'bg-slate-100 dark:bg-slate-950/50' : 
                            isWeekend ? 'bg-slate-50/50 dark:bg-slate-900/30' : ''
                        }`}
                    />
                    );
                })}
                </div>

                {/* Current Date Line */}
                {showNowLine && (
                    <div 
                        className="absolute bottom-0 border-l-2 border-dashed border-amber-500 z-50 pointer-events-none"
                        style={{ 
                            left: Math.max(nowOffsetDays * DAY_WIDTH, 0),
                            top: HEADER_HEIGHT, 
                        }}
                    >
                        <div 
                            className="absolute -top-3 text-[9px] font-bold text-white bg-amber-600 dark:bg-amber-500 px-2 py-1 rounded shadow-md whitespace-nowrap ring-2 ring-white dark:ring-slate-900 z-50 transition-transform duration-300"
                            style={{
                                left: 0,
                                transform: nowOffsetDays * DAY_WIDTH < 25 ? 'none' : 'translateX(-50%)'
                            }}
                        >
                            Today
                        </div>
                    </div>
                )}

                {/* Dependency Lines (SVG Layer) */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ marginTop: HEADER_HEIGHT }}>
                <defs>
                    <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                    <polygon points="0 0, 6 2, 0 4" fill={isDarkMode ? "#64748b" : "#94a3b8"} />
                    </marker>
                </defs>
                {tasks.map(task => 
                    task.predecessors.map(predId => {
                    const pred = tasks.find(p => p.id === predId);
                    if (!pred) return null;

                    // Coordinates
                    // We target the center of the main bar (top: 16, height: 20 -> center 26)
                    // SHIFT: Add VISUAL_SHIFT_DAYS to offsets
                    const startX = (pred.startOffsetDays + pred.durationDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const startY = (pred.rowIndex * ROW_HEIGHT) + 26; 
                    const endX = (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                    const endY = (task.rowIndex * ROW_HEIGHT) + 26;

                    // Curve logic
                    const gap = endX - startX;
                    const midX = startX + (gap > 20 ? 15 : gap/2);

                    return (
                        <path
                        key={`${pred.id}-${task.id}`}
                        d={`M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${endY} L ${endX} ${endY}`}
                        fill="none"
                        stroke={isDarkMode ? "#64748b" : "#94a3b8"}
                        strokeWidth="1.5"
                        strokeDasharray="3 3"
                        markerEnd="url(#arrowhead)"
                        className="transition-all duration-300 opacity-50"
                        />
                    );
                    })
                )}
                </svg>

                {/* Task Bars */}
                <div className="absolute top-0 left-0 w-full z-10" style={{ marginTop: HEADER_HEIGHT }}>
                {tasks.map((task) => {
                    // Find corresponding realistic task
                    const realistic = realisticTasks?.find(t => t.id === task.id);
                    // Find corresponding max velocity task
                    const maxVel = maxVelocityTasks?.find(t => t.id === task.id);

                    // Find corresponding baseline task (Ghost Main)
                    const baseline = baselineTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline realistic (Ghost Realistic)
                    const baselineRealistic = baselineRealisticTasks?.find(t => t.id === task.id);
                    // Find corresponding baseline max velocity (Ghost Max Vel - Immutable)
                    const baselineMaxVel = baselineMaxVelocityTasks?.find(t => t.id === task.id);

                    const isDone = task.isCompleted;

                    return (
                        <div
                        key={task.id}
                        style={{
                            height: ROW_HEIGHT,
                            width: '100%',
                            position: 'relative'
                        }}
                        >
                        {/* 1. Ghost Realistic Bar (Green Dashed) - Top symmetric (6px) */}
                        {baselineRealistic && (
                            <div
                                className="absolute rounded-sm border border-emerald-300 dark:border-emerald-700/50 bg-emerald-100/30 dark:bg-emerald-900/10 pointer-events-none"
                                style={{
                                    left: (baselineRealistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineRealistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6, 
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 2. Ghost Max Velocity Bar (Red Dashed) - Bottom symmetric (42px) */}
                        {baselineMaxVel && (
                             <div
                                className="absolute rounded-sm border border-rose-300 dark:border-rose-700/50 bg-rose-100/30 dark:bg-rose-900/10 pointer-events-none"
                                style={{
                                    left: (baselineMaxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baselineMaxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 3. Ghost Main Bar (Gray Dashed) - Center symmetric (19px) */}
                        {baseline && (
                             <div
                                className="absolute rounded-sm bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 pointer-events-none"
                                style={{
                                    left: (baseline.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(baseline.durationDays * DAY_WIDTH, 4),
                                    height: 14,
                                    top: 19,
                                    opacity: 0.5,
                                    borderStyle: 'dashed'
                                }}
                            />
                        )}

                        {/* 4. Live Max Velocity Bar (Red Solid) - Bottom symmetric (42px) */}
                        {!isDone && maxVel && (
                             <div
                                className="absolute rounded-sm bg-rose-400/80 dark:bg-rose-500/80 pointer-events-none z-10"
                                style={{
                                    left: (maxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(maxVel.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 42,
                                }}
                            />
                        )}

                         {/* 5. Live Realistic Bar (Green Solid) - Top symmetric (6px) */}
                         {!isDone && realistic && (
                             <div
                                className="absolute rounded-sm bg-emerald-400/80 dark:bg-emerald-500/80 pointer-events-none z-10"
                                style={{
                                    left: (realistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                    width: Math.max(realistic.durationDays * DAY_WIDTH, 4),
                                    height: 4,
                                    top: 6,
                                }}
                            />
                        )}

                        {/* 6. MAIN TASK BAR - Center (16px) */}
                        <div
                            className={`absolute rounded shadow-sm border flex items-center justify-center z-20 group cursor-help transition-all duration-300 ${
                                getPhaseColor(task.phase)
                            } ${isDone ? 'opacity-75 saturate-75' : ''}`}
                            style={{
                                left: (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                width: Math.max(task.durationDays * DAY_WIDTH, 4),
                                height: 20,
                                top: 16,
                            }}
                            onMouseEnter={(e) => {
                                const rect = e.currentTarget.getBoundingClientRect();
                                setActiveTooltip({
                                    x: rect.left + (rect.width / 2),
                                    y: rect.top,
                                    task,
                                    realistic
                                });
                            }}
                            onMouseLeave={() => setActiveTooltip(null)}
                        >
                             {/* Black Strikethrough Line for Done state */}
                             {isDone && (
                                <div className="absolute w-full h-[3px] bg-slate-950 dark:bg-white z-30 pointer-events-none" />
                             )}

                             {/* Label inside bar if wide enough */}
                             {(task.durationDays * DAY_WIDTH) > 60 && (
                                <span className="text-[9px] font-bold truncate px-2 text-white z-20 relative">
                                    {isDone ? 'DONE' : `${task.duration_hours}h`}
                                </span>
                             )}
                        </div>
                    </div>
                  );
                })}
              </div>
            </div>
        </div>
      </div>

      {/* PORTALED TOOLTIP OVERLAY */}
      {activeTooltip && typeof document !== 'undefined' && createPortal(
            <div 
                className="fixed z-[9999] pointer-events-none print:hidden"
                style={{ 
                    left: activeTooltip.x, 
                    top: activeTooltip.y,
                    transform: 'translate(-50%, -100%)',
                    marginTop: '-8px'
                }}
            >
                <div className="bg-slate-900 text-white text-xs rounded-lg p-3 shadow-xl w-48 border border-slate-700">
                    <div className="font-bold mb-1">{activeTooltip.task.task_name}</div>
                    <div className="text-slate-400 mb-2">{activeTooltip.task.phase}</div>
                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div>
                            <span className="block text-slate-500">Start</span>
                            {activeTooltip.task.startDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">End</span>
                            {activeTooltip.task.endDate.toLocaleDateString()}
                        </div>
                        <div>
                            <span className="block text-slate-500">Duration</span>
                            {activeTooltip.task.duration_hours}h
                        </div>
                        {!activeTooltip.task.isCompleted && activeTooltip.realistic && (
                            <div>
                                <span className="block text-emerald-400">Realistic End</span>
                                {activeTooltip.realistic.endDate.toLocaleDateString()}
                            </div>
                        )}
                    </div>
                </div>
                {/* Triangle */}
                <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900 mx-auto"></div>
            </div>,
            document.body
       )}
    </div>
  );
};

import { Task, ProcessedTask } from '../types';

export const calculateProjectSchedule = (
  tasks: Task[], 
  weekdayHours: number, 
  weekendHours: number,
  projectStartTime?: Date,
  currentDate?: Date // New parameter for rescheduling logic
): ProcessedTask[] => {
  const taskMap = new Map<string, ProcessedTask>();

  // Use provided start date or default to today
  const projectStartDate = projectStartTime ? new Date(projectStartTime) : new Date();
  projectStartDate.setHours(9, 0, 0, 0); // Start at 9 AM

  // Helper to get capacity for a specific date
  const getDailyCapacity = (date: Date): number => {
      const day = date.getDay();
      const isWeekend = day === 0 || day === 6;
      return isWeekend ? weekendHours : weekdayHours;
  };

  // Helper: Find the next valid working moment
  const alignToNextWorkingTime = (date: Date): Date => {
      let current = new Date(date);
      let loops = 0;

      while (loops < 365) { 
        loops++;
        const capacity = getDailyCapacity(current);
        const workStart = new Date(current);
        workStart.setHours(9, 0, 0, 0);
        const workEnd = new Date(workStart);
        workEnd.setMinutes(workStart.getMinutes() + (capacity * 60));

        if (capacity <= 0) {
            current.setDate(current.getDate() + 1);
            current.setHours(9, 0, 0, 0);
            continue;
        }
        if (current < workStart) return workStart;
        if (current >= workEnd) {
            current.setDate(current.getDate() + 1);
            current.setHours(9, 0, 0, 0);
            continue;
        }
        return current;
      }
      return current;
  };

  // Helper: Add working hours (Forward)
  const addWorkingTime = (start: Date, hours: number): Date => {
    if (hours <= 0) return new Date(start);
    let current = new Date(start);
    current = alignToNextWorkingTime(current);

    let minutesRemaining = hours * 60;
    let loops = 0;

    while (minutesRemaining > 0.01 && loops < 10000) {
      loops++;
      const capacity = getDailyCapacity(current);
      const workStart = new Date(current);
      workStart.setHours(9, 0, 0, 0);
      const workEnd = new Date(workStart);
      workEnd.setMinutes(workStart.getMinutes() + (capacity * 60));

      if (capacity <= 0 || current >= workEnd) {
         current.setDate(current.getDate() + 1);
         current.setHours(9, 0, 0, 0);
         continue;
      }
      if (current < workStart) current = new Date(workStart);

      const minutesAvailableToday = (workEnd.getTime() - current.getTime()) / (1000 * 60);
      const minutesToWork = Math.min(minutesRemaining, minutesAvailableToday);

      current.setTime(current.getTime() + (minutesToWork * 60 * 1000));
      minutesRemaining -= minutesToWork;
    }
    return current;
  };

  // Helper: Subtract working hours (Backward) - For Completed Tasks
  const subtractWorkingTime = (end: Date, hours: number): Date => {
      if (hours <= 0) return new Date(end);

      let current = new Date(end);
      let remaining = hours;
      let loops = 0;
      let isFirstIter = true;

      while (remaining > 0.001 && loops < 10000) {
          loops++;

          const capacity = getDailyCapacity(current);
          const dayStart = new Date(current);
          dayStart.setHours(9, 0, 0, 0);

          const dayEnd = new Date(dayStart);
          dayEnd.setMinutes(dayStart.getMinutes() + (capacity * 60));

          // If no capacity or strictly before working hours, jump to previous day
          if (capacity <= 0 || current < dayStart) {
              current.setDate(current.getDate() - 1);
              current.setHours(23, 59, 59, 999); 
              isFirstIter = false;
              continue;
          }

          // If we are after the working window (e.g. spilled over from future, or overtime completion)
          // For consistency with "parks itself on that day", if it's overtime (first iter), we preserve it?
          // BUT, to respect "broken down" and capacity limits, we generally snap to window.
          // Let's Snap to dayEnd if it's past dayEnd. 
          if (current > dayEnd) {
              current = new Date(dayEnd);
          }

          const msAvailable = current.getTime() - dayStart.getTime();
          const hoursAvailable = msAvailable / (1000 * 60 * 60);

          const toConsume = Math.min(remaining, hoursAvailable);

          remaining -= toConsume;
          current.setTime(current.getTime() - (toConsume * 60 * 60 * 1000));

          if (remaining > 0.001) {
              // We hit dayStart. Jump to prev day end.
              current.setDate(current.getDate() - 1);
              current.setHours(23, 59, 59, 999);
          }
          isFirstIter = false;
      }
      return current;
  };

  // Recursive resolver for dependencies
  const resolveTask = (taskId: string, visited = new Set<string>()): ProcessedTask | null => {
    if (visited.has(taskId)) return null; 
    visited.add(taskId);

    const task = tasks.find(t => t.id === taskId);
    if (!task) return null;

    if (taskMap.has(taskId)) return taskMap.get(taskId)!;

    // 1. Resolve Predecessors to find dependencies anchor
    let dependencyEndTime = projectStartDate.getTime();

    task.predecessors.forEach(predId => {
      const predTask = resolveTask(predId, new Set(visited));
      if (predTask) {
        // Standard dependency logic: Start after Predecessor Ends.
        // Even for completed tasks, we respect their actual finish time as the anchor.
        const effectivePredEnd = predTask.endDate.getTime();

        if (effectivePredEnd > dependencyEndTime) {
            dependencyEndTime = effectivePredEnd;
        }
      }
    });

    // 2. COMPLETED TASK LOGIC (REAL WORKLOAD FIX)
    // If the task is done, we anchor it to the Completion Date (EndDate).
    // We calculate the StartDate backwards respecting capacity (Reverse Scheduling).
    if (task.isCompleted && task.completionDate) {
        const recordedCompletion = new Date(task.completionDate);
        if (!isNaN(recordedCompletion.getTime()) && recordedCompletion.getFullYear() > 2000) {

             const finalEnd = new Date(recordedCompletion);
             // Use reverse capacity scheduling instead of linear subtraction
             const finalStart = subtractWorkingTime(finalEnd, task.duration_hours);

             const diffTime = finalStart.getTime() - projectStartDate.getTime();
             const startOffsetDays = diffTime / (1000 * 60 * 60 * 24); 

             const durationDiff = finalEnd.getTime() - finalStart.getTime();
             const durationDays = durationDiff / (1000 * 60 * 60 * 24);

             const processed: ProcessedTask = {
               ...task,
               startDate: finalStart,
               endDate: finalEnd,
               startOffsetDays,
               durationDays,
               rowIndex: tasks.findIndex(t => t.id === taskId)
             };
             taskMap.set(taskId, processed);
             return processed;
        }
    }

    // 3. INCOMPLETE TASK LOGIC
    // Start Time is Predecessors End
    let startTime = dependencyEndTime;

    // Rescheduling logic for LIVE mode (incomplete tasks push to Now)
    if (currentDate && !task.isCompleted) {
        const nowTime = currentDate.getTime();
        // If the task SHOULD have started by now but hasn't, push it to now.
        if (startTime < nowTime) {
            startTime = nowTime;
        }
    }

    const startDate = alignToNextWorkingTime(new Date(startTime));
    const endDate = addWorkingTime(startDate, task.duration_hours);

    const diffTime = startDate.getTime() - projectStartDate.getTime();
    const startOffsetDays = Math.max(0, diffTime / (1000 * 60 * 60 * 24)); 

    const durationDiff = endDate.getTime() - startDate.getTime();
    const durationDays = Math.max(0.1, durationDiff / (1000 * 60 * 60 * 24));

    const processed: ProcessedTask = {
      ...task,
      startDate,
      endDate,
      startOffsetDays,
      durationDays,
      rowIndex: tasks.findIndex(t => t.id === taskId)
    };

    taskMap.set(taskId, processed);
    return processed;
  };

  tasks.forEach(t => resolveTask(t.id));
  return Array.from(taskMap.values()).sort((a, b) => a.rowIndex - b.rowIndex);
};

export interface DailyWorkload {
  date: string;
  hours: number;
  label: string;
  tooltipLabel: string;
  isWeekend: boolean;
  limit: number;
  [key: string]: any; 
}

export const calculateDailyWorkload = (
  tasks: ProcessedTask[], 
  weekdayHours: number, 
  weekendHours: number
): DailyWorkload[] => {
  if (tasks.length === 0) return [];

  let minDate = new Date(tasks[0].startDate);
  let maxDate = new Date(tasks[0].endDate);

  tasks.forEach(t => {
    if (t.startDate < minDate) minDate = new Date(t.startDate);
    if (t.endDate > maxDate) maxDate = new Date(t.endDate);
  });

  const startCursor = new Date(minDate);
  startCursor.setHours(0, 0, 0, 0);

  const endCursor = new Date(maxDate);
  endCursor.setHours(23, 59, 59, 999);

  const dailyData: DailyWorkload[] = [];
  const oneHour = 60 * 60 * 1000;

  for (let d = new Date(startCursor); d <= endCursor; d.setDate(d.getDate() + 1)) {
    const dayStart = new Date(d);

    const isWeekend = d.getDay() === 0 || d.getDay() === 6;
    const limit = isWeekend ? weekendHours : weekdayHours;

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const localDateStr = `${year}-${month}-${day}`;

    const dailyEntry: DailyWorkload = {
      date: localDateStr,
      hours: 0,
      label: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
      tooltipLabel: d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }),
      isWeekend,
      limit
    };

    let hoursToday = 0;

    tasks.forEach(task => {
      // HYBRID WORKLOAD CALCULATION
      // 1. If Incomplete (Scheduled): We assume work only happens during working hours (9am - limit).
      //    This prevents gaps (nights/weekends) from counting as work.
      // 2. If Completed (Actuals): We assume the work happened continuously between Start and End,
      //    even if it was late at night or overtime. We check the FULL day intersection.

      let startWindow: number;
      let endWindow: number;

      // UPDATED LOGIC FOR WORKLOAD CHART:
      // Even for completed tasks, since we now calculate their StartDate using Capacity constraints (skipping nights/weekends),
      // we should align the Workload calculation to match that capacity curve, otherwise we get "ghost hours" at night.
      // However, the prompt specifically asked for "parks itself on that day", implying filling the capacity.

      // Let's treat ALL tasks as bound by working hours for the Workload Chart to be consistent with the Capacity Simulator.
      // Exception: If a task has duration > 0 on a day, it counts.

      const workingDayStart = new Date(d);
      workingDayStart.setHours(9, 0, 0, 0);
      const workingDayEnd = new Date(workingDayStart);
      workingDayEnd.setTime(workingDayStart.getTime() + (limit * oneHour));
      startWindow = workingDayStart.getTime();
      endWindow = workingDayEnd.getTime();

      // But wait, if we used `subtractWorkingTime`, the start/end might fall outside 9am window if we didn't clamp?
      // We added clamping in subtractWorkingTime, so Start/End should be mostly aligned with working hours.
      // EXCEPT the completion moment might be late (e.g. 8pm).
      // So we should expand the window to include task.endDate if it's on this day?

      // Simpler approach: Intersection of (TaskStart, TaskEnd) and (DayStart 00:00, DayEnd 23:59).
      // Then clamp that duration to 'limit' if it exceeds it? No, that hides overtime.

      // Let's stick to the previous hybrid logic but refined:
      // If completed, we trust the Start/End we just calculated. 
      // Since Start/End now skip non-working time, a linear intersection with 24h day 
      // might still pick up the "skipped" weekend time if the bar spans it visually?
      // Yes. `ProcessedTask` has a single Start and End. It implies continuity.
      // If Start=Friday 5pm, End=Monday 9am.
      // Intersection with Saturday is 24h.
      // But we know capacity was 0.

      // FIX: Use `getDailyCapacity` logic inside workload calculation too.
      // Only count intersection with WORKING WINDOW of that day.

      if (limit > 0) {
          const taskStart = task.startDate.getTime();
          const taskEnd = task.endDate.getTime();

          // Intersection of Task and Working Window
          const overlapStart = Math.max(taskStart, startWindow);
          const overlapEnd = Math.min(taskEnd, endWindow);

          if (overlapEnd > overlapStart) {
              const h = (overlapEnd - overlapStart) / oneHour;
              hoursToday += h;
              if (task.phase) {
                  dailyEntry[task.phase] = (dailyEntry[task.phase] || 0) + h;
              }
          }
      }
    });

    dailyEntry.hours = Number(hoursToday.toFixed(2));

    Object.keys(dailyEntry).forEach(key => {
        if (typeof dailyEntry[key] === 'number' && key !== 'hours' && key !== 'limit') {
             dailyEntry[key] = Number((dailyEntry[key] as number).toFixed(2));
        }
    });

    dailyData.push(dailyEntry);
  }

  return dailyData;
};

import { Task, ProcessedTask } from '../types';

// Helper interface for the global capacity ledger
interface DayLedger {
  [dateStr: string]: number; // 'YYYY-MM-DD': hours_used
}

export const calculateProjectSchedule = (
  tasks: Task[], 
  weekdayHours: number, 
  weekendHours: number,
  projectStartTime?: Date,
  currentDate?: Date
): ProcessedTask[] => {
  const taskMap = new Map<string, ProcessedTask>();
  const capacityLedger: DayLedger = {};

  // Use provided start date or default to today
  const projectStartDate = projectStartTime ? new Date(projectStartTime) : new Date();
  projectStartDate.setHours(9, 0, 0, 0); 

  // --- HELPERS ---

  const getDateKey = (d: Date) => {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  };

  const getDailyLimit = (d: Date): number => {
      const day = d.getDay();
      const isWeekend = day === 0 || day === 6;
      return isWeekend ? weekendHours : weekdayHours;
  };

  const getRemainingCapacity = (d: Date): number => {
      const key = getDateKey(d);
      const limit = getDailyLimit(d);
      const used = capacityLedger[key] || 0;
      return Math.max(0, limit - used);
  };

  const consumeCapacity = (d: Date, hours: number) => {
      const key = getDateKey(d);
      const current = capacityLedger[key] || 0;
      capacityLedger[key] = current + hours;
  };

  // --- 1. PROCESS COMPLETED TASKS (REVERSE FILL) ---
  // We process them in order of completion to ensure the "timeline" of the day fills up naturally.
  // Earliest completed tasks get the capacity first? 
  // Prompt: "available time left over after previous tasks were performed".
  // This implies chronological order of completion dictates who gets the slot.

  const completedTasks = tasks.filter(t => t.isCompleted && t.completionDate)
    .sort((a, b) => new Date(a.completionDate!).getTime() - new Date(b.completionDate!).getTime());

  completedTasks.forEach(task => {
      const completionDate = new Date(task.completionDate!);
      let remainingDuration = task.duration_hours;
      let currentCursor = new Date(completionDate);

      // If the completion time is extremely early (e.g. 2am), and we have a cutoff, 
      // the date logic in App.tsx handles the business day. We assume completionDate is correct here.

      // We determine the "Start Date" by consuming capacity backwards.
      let lastValidStart = new Date(currentCursor);

      while (remainingDuration > 0.001) {
          const dailyLimit = getDailyLimit(currentCursor);

          if (dailyLimit > 0) {
              const available = getRemainingCapacity(currentCursor);

              if (available > 0) {
                  const toAlloc = Math.min(remainingDuration, available);
                  consumeCapacity(currentCursor, toAlloc);
                  remainingDuration -= toAlloc;
                  lastValidStart = new Date(currentCursor); // Track where we are
              }
          }

          if (remainingDuration > 0.001) {
              // Move to previous day
              currentCursor.setDate(currentCursor.getDate() - 1);
              // Reset time to end of day for logic's sake (though we rely on ledger for capacity)
              currentCursor.setHours(17, 0, 0, 0); 

              // Failsafe for infinite loops (e.g. if capacity is 0 everywhere)
              if (currentCursor.getFullYear() < 2000) break;
          }
      }

      // Start Date is roughly where we stopped. 
      // For visual Gantt, we set StartDate to the beginning of that work-block? 
      // Or just the date? Let's use the 9AM anchor of the calculated start day.
      const calculatedStart = new Date(currentCursor);
      calculatedStart.setHours(9, 0, 0, 0);

      const diffTime = calculatedStart.getTime() - projectStartDate.getTime();
      const startOffsetDays = diffTime / (1000 * 60 * 60 * 24);

      const durationDiff = completionDate.getTime() - calculatedStart.getTime();
      const durationDays = durationDiff / (1000 * 60 * 60 * 24);

      const processed: ProcessedTask = {
          ...task,
          startDate: calculatedStart,
          endDate: completionDate,
          startOffsetDays,
          durationDays,
          rowIndex: 0 // Will fix later
      };
      taskMap.set(task.id, processed);
  });

  // --- 2. PROCESS INCOMPLETE TASKS (FORWARD FILL) ---
  // Standard recursive resolution, but checking the global ledger.

  const resolveIncomplete = (taskId: string, visited = new Set<string>()): ProcessedTask | null => {
      if (visited.has(taskId)) return null;
      visited.add(taskId);

      // If already processed (completed), return it
      if (taskMap.has(taskId)) return taskMap.get(taskId)!;

      const task = tasks.find(t => t.id === taskId);
      if (!task) return null;

      // Resolve Predecessors to find earliest possible start
      let dependencyEnd = projectStartDate.getTime();

      task.predecessors.forEach(predId => {
          const pred = resolveIncomplete(predId, new Set(visited));
          if (pred) {
              if (pred.endDate.getTime() > dependencyEnd) {
                  dependencyEnd = pred.endDate.getTime();
              }
          }
      });

      // LIVE Mode adjustment: If today is later than dependency, start today
      if (currentDate) {
          if (currentDate.getTime() > dependencyEnd) {
              dependencyEnd = currentDate.getTime();
          }
      }

      let currentCursor = new Date(dependencyEnd);
      // Align to start of a working slot if needed, or just keep timestamp
      // But we must respect "Next Available Slot" in the ledger.

      // Find first day with capacity from currentCursor onwards
      let findingSlot = true;
      while (findingSlot) {
          const cap = getRemainingCapacity(currentCursor);
          if (cap > 0) {
              findingSlot = false;
          } else {
              // Move to next day 9am
              currentCursor.setDate(currentCursor.getDate() + 1);
              currentCursor.setHours(9, 0, 0, 0);

              // Failsafe
              if (currentCursor.getFullYear() > 2030) break;
          }
      }

      const actualStart = new Date(currentCursor);
      let remainingDuration = task.duration_hours;

      // Consume forward
      while (remainingDuration > 0.001) {
          const limit = getDailyLimit(currentCursor);

          if (limit > 0) {
              const available = getRemainingCapacity(currentCursor);
              if (available > 0) {
                  const toAlloc = Math.min(remainingDuration, available);
                  consumeCapacity(currentCursor, toAlloc);
                  remainingDuration -= toAlloc;
              }
          }

          if (remainingDuration > 0.001) {
               // Move to next day
               currentCursor.setDate(currentCursor.getDate() + 1);
               currentCursor.setHours(9, 0, 0, 0);
          }
      }

      const actualEnd = new Date(currentCursor);
      // If we finished exactly at 9am of next day, visually snap back to end of prev day?
      // No, let's keep it accurate.

      const diffTime = actualStart.getTime() - projectStartDate.getTime();
      const startOffsetDays = Math.max(0, diffTime / (1000 * 60 * 60 * 24));

      const durationDiff = actualEnd.getTime() - actualStart.getTime();
      const durationDays = Math.max(0.1, durationDiff / (1000 * 60 * 60 * 24));

      const processed: ProcessedTask = {
          ...task,
          startDate: actualStart,
          endDate: actualEnd,
          startOffsetDays,
          durationDays,
          rowIndex: 0
      };

      taskMap.set(taskId, processed);
      return processed;
  };

  // Run resolution for all tasks
  tasks.forEach(t => resolveIncomplete(t.id));

  // Assign Row Indices based on original order
  const result = Array.from(taskMap.values());
  const final = result.map(p => {
      const idx = tasks.findIndex(t => t.id === p.id);
      return { ...p, rowIndex: idx };
  });

  return final.sort((a, b) => a.rowIndex - b.rowIndex);
};

export interface DailyWorkload {
  date: string;
  hours: number;
  label: string;
  tooltipLabel: string;
  isWeekend: boolean;
  limit: number;
  [key: string]: any; 
}

// Rewritten Workload Calculator to use the same logic of distribution
export const calculateDailyWorkload = (
  tasks: ProcessedTask[], 
  weekdayHours: number, 
  weekendHours: number
): DailyWorkload[] => {
  if (tasks.length === 0) return [];

  // Determine Range
  let minDate = new Date(tasks[0].startDate);
  let maxDate = new Date(tasks[0].endDate);
  tasks.forEach(t => {
    if (t.startDate < minDate) minDate = new Date(t.startDate);
    if (t.endDate > maxDate) maxDate = new Date(t.endDate);
  });

  // Normalize range
  const startCursor = new Date(minDate); startCursor.setHours(0,0,0,0);
  const endCursor = new Date(maxDate); endCursor.setHours(23,59,59,999);

  // Initialize Maps
  const workloadMap = new Map<string, DailyWorkload>();
  const capacityMap = new Map<string, number>(); // Date -> Used Capacity

  // Pre-fill Timeline
  for (let d = new Date(startCursor); d <= endCursor; d.setDate(d.getDate() + 1)) {
    const isWeekend = d.getDay() === 0 || d.getDay() === 6;
    const limit = isWeekend ? weekendHours : weekdayHours;

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const dateKey = `${year}-${month}-${day}`;

    workloadMap.set(dateKey, {
        date: dateKey,
        hours: 0,
        label: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        tooltipLabel: d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }),
        isWeekend,
        limit
    });
    capacityMap.set(dateKey, 0);
  }

  // --- DISTRIBUTE HOURS (Replicating Scheduling Logic) ---
  // We must respect the rule: Capacity Limits.
  // Completed tasks fill backwards, Incomplete fill forwards.
  // But here we just need to place the hours "where they fit" inside the Start-End window.

  // NOTE: Ideally, the Scheduler should return the 'segments' of work.
  // Since it doesn't, we approximate by distributing the Duration across the valid days in the Start-End range.

  tasks.forEach(task => {
      let remaining = task.duration_hours;
      const start = new Date(task.startDate);
      const end = new Date(task.endDate);

      // Generate array of days between start and end
      const daysInRange: string[] = [];
      let iter = new Date(start);
      iter.setHours(0,0,0,0);
      const endCap = new Date(end);
      endCap.setHours(23,59,59,999);

      while (iter <= endCap) {
          const y = iter.getFullYear();
          const m = String(iter.getMonth() + 1).padStart(2, '0');
          const d = String(iter.getDate()).padStart(2, '0');
          daysInRange.push(`${y}-${m}-${d}`);
          iter.setDate(iter.getDate() + 1);
      }

      // If task is completed, we fill from End Day backwards
      if (task.isCompleted) {
          daysInRange.reverse();
      }

      // Distribute
      for (const dateKey of daysInRange) {
          if (remaining <= 0.001) break;

          const dayData = workloadMap.get(dateKey);
          if (!dayData) continue; // Out of range?

          const limit = dayData.limit;
          const used = capacityMap.get(dateKey) || 0;
          const available = Math.max(0, limit - used);

          if (available > 0) {
              const toAdd = Math.min(remaining, available);

              // Update Workload Entry
              dayData.hours += toAdd;
              if (task.phase) {
                  dayData[task.phase] = (dayData[task.phase] || 0) + toAdd;
              }

              // Update Ledger
              capacityMap.set(dateKey, used + toAdd);
              remaining -= toAdd;
          }
      }

      // If remaining > 0 (because all days full?), force add to the primary anchor day (Start or End)
      // to avoid missing hours in the chart.
      if (remaining > 0.001) {
          const anchorKey = task.isCompleted ? daysInRange[0] : daysInRange[daysInRange.length - 1]; // End if completed (reversed), Start if incomplete? No, Incomplete fills forward.
          // Actually if incomplete fills forward, the last day is where it spills.
          // If completed fills backward, the first day (reverse[0] = end) is where it anchors.

          // Let's just dump it on the anchor to be safe, so totals match.
          // For incomplete: last day in range. For completed: first day in reversed range (which is end date).
          // Actually, let's just use the very last day we touched.
           const fallbackKey = daysInRange[daysInRange.length - 1];
           const dayData = workloadMap.get(fallbackKey);
           if (dayData) {
               dayData.hours += remaining;
               if (task.phase) dayData[task.phase] = (dayData[task.phase] || 0) + remaining;
           }
      }
  });

  // Rounding
  workloadMap.forEach(entry => {
      entry.hours = Number(entry.hours.toFixed(2));
      Object.keys(entry).forEach(key => {
          if (typeof entry[key] === 'number' && key !== 'hours' && key !== 'limit') {
              entry[key] = Number((entry[key] as number).toFixed(2));
          }
      });
  });

  return Array.from(workloadMap.values());
};

