export const calculateProjectSchedule = (
  tasks: Task[], 
  weekdayHours: number, 
  weekendHours: number,
  projectStartTime?: Date,
  currentDate?: Date
): ProcessedTask[] => {
  const taskMap = new Map<string, ProcessedTask>();
  const capacityLedger: DayLedger = {};

  // Use provided start date or default to today
  const projectStartDate = projectStartTime ? new Date(projectStartTime) : new Date();
  projectStartDate.setHours(9, 0, 0, 0); 

  // --- HELPERS ---

  const getDateKey = (d: Date) => {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  };

  const getDailyLimit = (d: Date): number => {
      const day = d.getDay();
      const isWeekend = day === 0 || day === 6;
      return isWeekend ? weekendHours : weekdayHours;
  };

  const getRemainingCapacity = (d: Date): number => {
      const key = getDateKey(d);
      const limit = getDailyLimit(d);
      const used = capacityLedger[key] || 0;
      return Math.max(0, limit - used);
  };

  const consumeCapacity = (d: Date, hours: number) => {
      const key = getDateKey(d);
      const current = capacityLedger[key] || 0;
      capacityLedger[key] = current + hours;
  };

  // --- TOPOLOGICAL SORT FOR INCOMPLETE TASKS ---
  // We need a robust order for incomplete tasks to respect dependencies.
  // Completed tasks are processed separately first.

  const getTopologicalOrder = (allTasks: Task[]): Task[] => {
      const visited = new Set<string>();
      const sorted: Task[] = [];
      const visit = (taskId: string) => {
          if (visited.has(taskId)) return;
          visited.add(taskId);
          const t = allTasks.find(x => x.id === taskId);
          if (t) {
              t.predecessors.forEach(p => visit(p));
              sorted.push(t);
          }
      };
      allTasks.forEach(t => visit(t.id));
      return sorted;
  };

  const sortedTasks = getTopologicalOrder(tasks);

  // 1. Process COMPLETED Tasks First (Fixed Anchors)
  // They are anchored to their completionDate.
  // "When a task is done, it parks itself on that day... difference scheduled for the next day."
  const completedTasks = tasks.filter(t => t.isCompleted && t.completionDate)
    .sort((a, b) => new Date(a.completionDate!).getTime() - new Date(b.completionDate!).getTime());

  // 2. Process INCOMPLETE Tasks Second (Floating)
  // They respect dependencies (which might include completed tasks)
  const incompleteTasks = sortedTasks.filter(t => !t.isCompleted || !t.completionDate);

  // --- SHARED ALLOCATION LOGIC ---
  const scheduleTask = (task: Task, anchorDate: Date, isFixedStart: boolean) => {
      let remainingDuration = task.duration_hours;
      let currentCursor = new Date(anchorDate);

      // Ensure we start at 9am context for logic consistency
      currentCursor.setHours(9, 0, 0, 0);

      const distribution: Record<string, number> = {};

      // Optimization: Failsafe loop count
      let loops = 0;
      let actualStartDate: Date | null = null;
      let lastDate: Date = new Date(currentCursor);

      // If Incomplete (Floating), we must find the first day with ANY capacity
      // If Completed (Fixed), we force start on the anchor day, even if capacity is full (it spills immediately)
      if (!isFixedStart) {
          while (loops < 1000) {
              const cap = getRemainingCapacity(currentCursor);
              if (cap > 0.001) break;
              currentCursor.setDate(currentCursor.getDate() + 1);
              currentCursor.setHours(9,0,0,0);
              loops++;
          }
      }

      // Record the visual start date
      actualStartDate = new Date(currentCursor);

      loops = 0;
      while (remainingDuration > 0.001 && loops < 10000) {
          loops++;
          const dateKey = getDateKey(currentCursor);
          const limit = getDailyLimit(currentCursor);

          if (limit > 0) {
              const available = getRemainingCapacity(currentCursor);

              if (available > 0) {
                  const toAlloc = Math.min(remainingDuration, available);
                  consumeCapacity(currentCursor, toAlloc);

                  remainingDuration -= toAlloc;
                  distribution[dateKey] = (distribution[dateKey] || 0) + toAlloc;
                  lastDate = new Date(currentCursor);
              }
          }

          if (remainingDuration > 0.001) {
              // Move to next day
              currentCursor.setDate(currentCursor.getDate() + 1);
              currentCursor.setHours(9, 0, 0, 0);
          }
      }

      const actualEndDate = new Date(lastDate);
      // Set time to end of work day approx
      actualEndDate.setHours(17, 0, 0, 0);

      const diffTime = actualStartDate.getTime() - projectStartDate.getTime();
      const startOffsetDays = diffTime / (1000 * 60 * 60 * 24);

      const durationDiff = actualEndDate.getTime() - actualStartDate.getTime();
      const durationDays = durationDiff / (1000 * 60 * 60 * 24); // Visual days span

      const processed: ProcessedTask = {
          ...task,
          startDate: actualStartDate,
          endDate: actualEndDate,
          startOffsetDays,
          durationDays: Math.max(0.2, durationDays), // Ensure at least small visibility
          rowIndex: 0,
          scheduleDistribution: distribution
      };

      taskMap.set(task.id, processed);
  };

  // --- EXECUTE PASS 1: COMPLETED ---
  completedTasks.forEach(task => {
      // Anchor: Completion Date provided by user/system
      const anchor = new Date(task.completionDate!);
      scheduleTask(task, anchor, true); // true = Fixed Start (Parks on that day)
  });

  // --- EXECUTE PASS 2: INCOMPLETE ---
  incompleteTasks.forEach(task => {
      // Anchor: Max(Dependencies End, Project Start, Now)
      let anchor = projectStartDate.getTime();

      task.predecessors.forEach(pid => {
          const pred = taskMap.get(pid);
          if (pred) {
              // Standard Finish-to-Start: Start after predecessor ends
              // Use predecessor's calculated EndDate.
              // Note: If pred finished on Tuesday (full day), we start Wednesday?
              // The `scheduleTask` logic for Floating tasks finds the *Next Available Slot*.
              // So passing Pred.EndDate is correct; if Pred used up Tuesday, logic will skip to Wednesday.
              if (pred.endDate.getTime() > anchor) {
                  anchor = pred.endDate.getTime();
              }
          }
      });

      // Live Mode: If today is later than logic dictates, push to today
      if (currentDate) {
          const today9am = new Date(currentDate);
          today9am.setHours(9,0,0,0);
          if (today9am.getTime() > anchor) {
              anchor = today9am.getTime();
          }
      }

      scheduleTask(task, new Date(anchor), false); // false = Floating (Find capacity)
  });

  // Assign Row Indices based on original sort
  // Use the original passed order or topological? Original array order is usually preferred for UI stability.
  const result = Array.from(taskMap.values());
  const final = result.map(p => {
      const idx = tasks.findIndex(t => t.id === p.id);
      return { ...p, rowIndex: idx };
  });

  return final.sort((a, b) => a.rowIndex - b.rowIndex);
};

export interface DailyWorkload {
  date: string;
  hours: number;
  label: string;
  tooltipLabel: string;
  isWeekend: boolean;
  limit: number;
  [key: string]: any; 
}

export const calculateDailyWorkload = (
  tasks: ProcessedTask[], 
  weekdayHours: number, 
  weekendHours: number
): DailyWorkload[] => {
  if (tasks.length === 0) return [];

  let minDate = new Date(tasks[0].startDate);
  let maxDate = new Date(tasks[0].endDate);

  tasks.forEach(t => {
    if (t.startDate < minDate) minDate = new Date(t.startDate);
    if (t.endDate > maxDate) maxDate = new Date(t.endDate);
  });

  const startCursor = new Date(minDate);
  startCursor.setHours(0, 0, 0, 0);

  const endCursor = new Date(maxDate);
  endCursor.setHours(23, 59, 59, 999);

  // Pad the chart a bit if empty
  if (startCursor.getTime() === endCursor.getTime()) {
      endCursor.setDate(endCursor.getDate() + 7);
  }

  const workloadMap = new Map<string, DailyWorkload>();

  // Pre-fill Timeline
  for (let d = new Date(startCursor); d <= endCursor; d.setDate(d.getDate() + 1)) {
    const isWeekend = d.getDay() === 0 || d.getDay() === 6;
    const limit = isWeekend ? weekendHours : weekdayHours;

    const year = d.getFullYear();
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    const dateKey = `${year}-${month}-${day}`;

    workloadMap.set(dateKey, {
        date: dateKey,
        hours: 0,
        label: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        tooltipLabel: d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }),
        isWeekend,
        limit
    });
  }

  // --- AGGREGATE USING EXACT DISTRIBUTION FROM SCHEDULER ---
  tasks.forEach(task => {
      if (task.scheduleDistribution) {
          Object.entries(task.scheduleDistribution).forEach(([dateKey, hours]) => {
              const dayEntry = workloadMap.get(dateKey);
              // If day exists in range (it should)
              if (dayEntry) {
                  dayEntry.hours += hours;
                  if (task.phase) {
                      dayEntry[task.phase] = (dayEntry[task.phase] || 0) + hours;
                  }
              } else {
                  // Task might have spilled beyond our initial min/max calc?
                  // Should handle strictly but for now ignore or extend?
                  // In typical use, min/max covers all.
              }
          });
      }
  });

  // Formatting
  workloadMap.forEach(entry => {
    entry.hours = Number(entry.hours.toFixed(2));
    Object.keys(entry).forEach(key => {
        if (typeof entry[key] === 'number' && key !== 'hours' && key !== 'limit') {
             entry[key] = Number((entry[key] as number).toFixed(2));
        }
    });
  });

  return Array.from(workloadMap.values()).sort((a,b) => a.date.localeCompare(b.date));
};

import React, { useRef, useEffect, useState } from 'react';
import { createPortal } from 'react-dom';
import { ProcessedTask } from '../types';

interface GanttChartProps {
  tasks: ProcessedTask[];
  baselineTasks?: ProcessedTask[]; // Ghost main
  baselineRealisticTasks?: ProcessedTask[]; // Ghost realistic
  baselineMaxVelocityTasks?: ProcessedTask[]; // Ghost max velocity
  realisticTasks?: ProcessedTask[];
  maxVelocityTasks?: ProcessedTask[];
  weekendHours: number;
  weekdayHours?: number; // Added to calc intensity
  isDarkMode?: boolean;
  isPdfExport?: boolean;
  bufferPercent?: number;
  projectStartDate: Date;
  currentDate?: Date;
  onTaskToggle?: (taskId: string) => void;
  isExecutionMode?: boolean;
}

export const GanttChart: React.FC<GanttChartProps> = ({ 
  tasks, 
  baselineTasks,
  baselineRealisticTasks,
  baselineMaxVelocityTasks,
  realisticTasks, 
  maxVelocityTasks, 
  weekendHours, 
  weekdayHours = 8, // Default fallback
  isDarkMode = false,
  isPdfExport = false,
  bufferPercent = 30,
  projectStartDate,
  currentDate,
  onTaskToggle,
  isExecutionMode = false
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Tooltip State
  const [activeTooltip, setActiveTooltip] = useState<{
    x: number;
    y: number;
    task: ProcessedTask;
    realistic?: ProcessedTask;
    dailyInfo?: { date: string, hours: number, capacity: number };
  } | null>(null);

  useEffect(() => {
    const checkMobile = () => setIsMobile(window.innerWidth < 640);
    if (typeof window !== 'undefined') {
        checkMobile();
        window.addEventListener('resize', checkMobile);
    }
    return () => {
        if (typeof window !== 'undefined') window.removeEventListener('resize', checkMobile);
    }
  }, []);

  // Metrics
  const DAY_WIDTH = isPdfExport ? 25 : (isMobile ? 40 : 60);
  const HEADER_HEIGHT = 54;
  const ROW_HEIGHT = 52; 
  const SIDEBAR_WIDTH = isPdfExport ? 140 : (isMobile ? 50 : 200); 
  const VISUAL_SHIFT_DAYS = 1;

  const getEndDay = (taskList?: ProcessedTask[]) => 
    taskList ? taskList.reduce((acc, t) => Math.max(acc, t.startOffsetDays + t.durationDays), 0) : 0;

  const effectiveMaxDay = Math.max(
      getEndDay(tasks),
      getEndDay(realisticTasks),
      getEndDay(baselineTasks),
      getEndDay(baselineRealisticTasks),
      getEndDay(maxVelocityTasks),
      getEndDay(baselineMaxVelocityTasks)
  );

  const totalDays = effectiveMaxDay + 4 + VISUAL_SHIFT_DAYS; 
  const chartWidth = totalDays * DAY_WIDTH;
  const totalWidth = SIDEBAR_WIDTH + chartWidth;

  const now = currentDate || new Date();
  const diffTime = now.getTime() - projectStartDate.getTime();
  const nowOffsetDays = (diffTime / (1000 * 60 * 60 * 24)) + VISUAL_SHIFT_DAYS;
  const showNowLine = nowOffsetDays >= 0 && nowOffsetDays <= totalDays;

  const getDateLabel = (dayOffset: number) => {
    const d = new Date(projectStartDate);
    d.setDate(d.getDate() + dayOffset - VISUAL_SHIFT_DAYS);
    return {
      dateObj: d,
      weekday: d.toLocaleDateString('en-US', { weekday: 'short' }),
      day: d.getDate(),
      month: d.toLocaleDateString('en-US', { month: 'short' }),
      isWeekend: d.getDay() === 0 || d.getDay() === 6
    };
  };

  // Helper to calc offset from distribution key
  const getDayOffset = (dateStr: string) => {
      const [y, m, d] = dateStr.split('-').map(Number);
      const current = new Date(y, m - 1, d);
      const startZero = new Date(projectStartDate);
      startZero.setHours(0,0,0,0);
      const diff = current.getTime() - startZero.getTime();
      return Math.round(diff / (1000 * 60 * 60 * 24));
  };

  const getDayCapacity = (dateStr: string) => {
      const [y, m, d] = dateStr.split('-').map(Number);
      const date = new Date(y, m-1, d);
      const day = date.getDay();
      return (day === 0 || day === 6) ? weekendHours : weekdayHours;
  };

  const getPhaseColor = (phase: string) => {
    if (phase.includes('Design')) return 'bg-purple-500 border-purple-600';
    if (phase.includes('Frontend')) return 'bg-blue-500 border-blue-600';
    if (phase.includes('Backend') || phase.includes('Business')) return 'bg-indigo-500 border-indigo-600';
    if (phase.includes('Verification') || phase.includes('QA')) return 'bg-rose-500 border-rose-600';
    if (phase.includes('Deployment')) return 'bg-emerald-500 border-emerald-600';
    if (phase.includes('User')) return 'bg-amber-500 border-amber-600';
    return isDarkMode ? 'bg-slate-600 border-slate-700' : 'bg-slate-500 border-slate-600';
  };

  return (
    <div className={`gantt-container bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col ${isExecutionMode ? 'ring-2 ring-rose-500/20' : ''}`}>
      <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 flex flex-col xl:flex-row xl:justify-between xl:items-center gap-4">
        <div className="flex items-center gap-3">
            <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 whitespace-nowrap">Timeline & Dependencies</h3>
            {isExecutionMode && (
                <span className="bg-rose-500 text-white text-[10px] font-bold px-2 py-0.5 rounded shadow-sm uppercase tracking-wider animate-pulse">
                    Execution Mode
                </span>
            )}
        </div>

        <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs w-full xl:w-auto xl:justify-end">
           <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-4 mr-2">
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-emerald-500 rounded-sm"></span> Realistic (+{bufferPercent}%)
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 dark:text-slate-400">
                    <span className="w-8 h-2 bg-rose-500 rounded-sm"></span> Max Velocity
                </div>
           </div>
           <div className="flex flex-wrap items-center gap-3">
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400"><span className="w-2.5 h-2.5 bg-purple-500 rounded-sm"></span> Design</div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400"><span className="w-2.5 h-2.5 bg-blue-500 rounded-sm"></span> Frontend</div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400"><span className="w-2.5 h-2.5 bg-indigo-500 rounded-sm"></span> Logic</div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400"><span className="w-2.5 h-2.5 bg-rose-500 rounded-sm"></span> QA</div>
                <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-400"><span className="w-2.5 h-2.5 bg-emerald-500 rounded-sm"></span> Deploy</div>
           </div>
        </div>
      </div>

      <div className="gantt-scroll-area overflow-x-auto" ref={containerRef}>
        <div className="flex relative" style={{ width: totalWidth, height: (tasks.length * ROW_HEIGHT) + HEADER_HEIGHT + 20 }}>
            {/* Left Column: Task Names */}
            <div style={{ width: SIDEBAR_WIDTH }} className="sticky left-0 flex-shrink-0 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 z-30 shadow-[4px_0_12px_-4px_rgba(0,0,0,0.1)] dark:shadow-[4px_0_12px_-4px_rgba(0,0,0,0.3)] transition-all duration-300">
                <div style={{ height: HEADER_HEIGHT }} className={`sticky top-0 z-40 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 p-2 font-bold text-xs text-slate-500 dark:text-slate-400 uppercase tracking-wider flex items-center ${isMobile ? 'justify-center' : ''}`}>
                    {isMobile ? '#' : 'Task Name'}
                </div>
                {tasks.map((task) => {
                    const words = task.task_name.split(' ');
                    const shortName = words.slice(0, 3).join(' ') + (words.length > 3 ? '...' : '');
                    const hasUnfinishedPredecessors = task.predecessors.some(predId => {
                        const pred = tasks.find(t => t.id === predId);
                        return pred && !pred.isCompleted;
                    });
                    const isDependencyLocked = !task.isCompleted && hasUnfinishedPredecessors;
                    const textOpacityClass = isExecutionMode && !task.isCompleted ? 'opacity-80' : '';

                    return (
                        <div key={task.id} style={{ height: ROW_HEIGHT }} className={`border-b border-slate-100 dark:border-slate-800 px-3 flex items-center text-xs font-medium text-slate-700 dark:text-slate-300 ${isMobile ? 'justify-center' : ''}`} title={task.task_name}>
                            <div className="flex items-center w-full min-w-0">
                                <div onClick={() => !isDependencyLocked && onTaskToggle && onTaskToggle(task.id)} className={`flex items-center justify-center w-6 h-6 rounded-full border text-[10px] font-bold transition-all duration-200 flex-shrink-0 mr-2 z-10 relative ${task.isCompleted ? 'bg-black dark:bg-slate-200 text-white dark:text-slate-900 border-black dark:border-slate-200 ring-2 ring-indigo-500 ring-offset-2 dark:ring-offset-slate-900' : isDependencyLocked ? 'bg-slate-100 text-slate-300 border-slate-200 dark:bg-slate-800 dark:text-slate-600 dark:border-slate-700 cursor-not-allowed' : 'bg-white dark:bg-slate-900 text-slate-500 border-slate-300 dark:border-slate-600 hover:border-indigo-500 hover:text-indigo-600 cursor-pointer'} ${isExecutionMode && !task.isCompleted && !isDependencyLocked ? 'animate-pulse ring-1 ring-indigo-500/50' : ''}`}>
                                    {task.isCompleted ? '✓' : task.id}
                                </div>
                                {!isMobile && <span className={`truncate transition-opacity ${task.isCompleted ? 'text-slate-400 line-through' : (isDependencyLocked ? 'text-slate-400 dark:text-slate-600' : textOpacityClass)}`}>{shortName}</span>}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Right Column: Chart Area */}
            <div className="flex-1 relative h-full">
                {/* Timeline Header */}
                <div className="flex sticky top-0 left-0 right-0 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800 z-20" style={{ height: HEADER_HEIGHT }}>
                    {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                        const { day, month, weekday, isWeekend } = getDateLabel(i);
                        const isZeroWorkWeekend = isWeekend && weekendHours === 0;
                        return (
                            <div key={i} style={{ width: DAY_WIDTH }} className={`flex-shrink-0 flex flex-col items-center justify-center text-[10px] border-r border-slate-200 dark:border-slate-800 leading-tight ${isZeroWorkWeekend ? 'bg-slate-200 dark:bg-slate-950 text-slate-400 dark:text-slate-600' : isWeekend ? 'bg-slate-100 dark:bg-slate-900' : ''}`}>
                                <span className="text-[9px] uppercase font-bold text-slate-500 dark:text-slate-400">{weekday}</span>
                                <span className="font-bold text-slate-800 dark:text-slate-200 text-xs">{day}</span>
                                <span className="text-[9px] text-slate-400 dark:text-slate-500">{month}</span>
                            </div>
                        );
                    })}
                </div>

                {/* Grid Background */}
                <div className="absolute top-0 bottom-0 left-0 right-0 z-0 flex pointer-events-none">
                    {Array.from({ length: Math.ceil(totalDays) }).map((_, i) => {
                        const { isWeekend } = getDateLabel(i);
                        const isZeroWorkWeekend = isWeekend && weekendHours === 0;
                        return <div key={i} style={{ width: DAY_WIDTH }} className={`flex-shrink-0 border-r border-dashed border-slate-300 dark:border-slate-800 h-full ${isZeroWorkWeekend ? 'bg-slate-100 dark:bg-slate-950/50' : isWeekend ? 'bg-slate-50/50 dark:bg-slate-900/30' : ''}`} />;
                    })}
                </div>

                {/* Today Line */}
                {showNowLine && (
                    <div className="absolute bottom-0 border-l-2 border-dashed border-amber-500 z-50 pointer-events-none" style={{ left: Math.max(nowOffsetDays * DAY_WIDTH, 0), top: HEADER_HEIGHT }}>
                        <div className="absolute -top-3 text-[9px] font-bold text-white bg-amber-600 dark:bg-amber-500 px-2 py-1 rounded shadow-md whitespace-nowrap ring-2 ring-white dark:ring-slate-900 z-50 transition-transform duration-300" style={{ left: 0, transform: nowOffsetDays * DAY_WIDTH < 25 ? 'none' : 'translateX(-50%)' }}>Today</div>
                    </div>
                )}

                {/* Dependency Lines */}
                <svg className="absolute top-0 left-0 w-full h-full pointer-events-none z-0" style={{ marginTop: HEADER_HEIGHT }}>
                    <defs>
                        <marker id="arrowhead" markerWidth="6" markerHeight="4" refX="5" refY="2" orient="auto">
                            <polygon points="0 0, 6 2, 0 4" fill={isDarkMode ? "#64748b" : "#94a3b8"} />
                        </marker>
                    </defs>
                    {tasks.map(task => 
                        task.predecessors.map(predId => {
                            const pred = tasks.find(p => p.id === predId);
                            if (!pred) return null;
                            const startX = (pred.startOffsetDays + pred.durationDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                            const startY = (pred.rowIndex * ROW_HEIGHT) + 26; 
                            const endX = (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH;
                            const endY = (task.rowIndex * ROW_HEIGHT) + 26;
                            const gap = endX - startX;
                            const midX = startX + (gap > 20 ? 15 : gap/2);
                            return <path key={`${pred.id}-${task.id}`} d={`M ${startX} ${startY} L ${midX} ${startY} L ${midX} ${endY} L ${endX} ${endY}`} fill="none" stroke={isDarkMode ? "#64748b" : "#94a3b8"} strokeWidth="1.5" strokeDasharray="3 3" markerEnd="url(#arrowhead)" className="transition-all duration-300 opacity-50" />;
                        })
                    )}
                </svg>

                {/* Task Bars (Ghost + Broken Main) */}
                <div className="absolute top-0 left-0 w-full z-10" style={{ marginTop: HEADER_HEIGHT }}>
                    {tasks.map((task) => {
                        const realistic = realisticTasks?.find(t => t.id === task.id);
                        const maxVel = maxVelocityTasks?.find(t => t.id === task.id);
                        const baseline = baselineTasks?.find(t => t.id === task.id);
                        const baselineRealistic = baselineRealisticTasks?.find(t => t.id === task.id);
                        const baselineMaxVel = baselineMaxVelocityTasks?.find(t => t.id === task.id);
                        const isDone = task.isCompleted;

                        return (
                            <div key={task.id} style={{ height: ROW_HEIGHT, width: '100%', position: 'relative' }}>
                                {/* Ghost Bars (Continuous for context) */}
                                {baselineRealistic && <div className="absolute rounded-sm border border-emerald-300 dark:border-emerald-700/50 bg-emerald-100/30 dark:bg-emerald-900/10 pointer-events-none" style={{ left: (baselineRealistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(baselineRealistic.durationDays * DAY_WIDTH, 4), height: 4, top: 6, borderStyle: 'dashed' }} />}
                                {baselineMaxVel && <div className="absolute rounded-sm border border-rose-300 dark:border-rose-700/50 bg-rose-100/30 dark:bg-rose-900/10 pointer-events-none" style={{ left: (baselineMaxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(baselineMaxVel.durationDays * DAY_WIDTH, 4), height: 4, top: 42, borderStyle: 'dashed' }} />}
                                {baseline && <div className="absolute rounded-sm bg-slate-100 dark:bg-slate-800 border border-slate-300 dark:border-slate-600 pointer-events-none" style={{ left: (baseline.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(baseline.durationDays * DAY_WIDTH, 4), height: 14, top: 19, opacity: 0.5, borderStyle: 'dashed' }} />}
                                {!isDone && maxVel && <div className="absolute rounded-sm bg-rose-400/80 dark:bg-rose-500/80 pointer-events-none z-10" style={{ left: (maxVel.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(maxVel.durationDays * DAY_WIDTH, 4), height: 4, top: 42 }} />}
                                {!isDone && realistic && <div className="absolute rounded-sm bg-emerald-400/80 dark:bg-emerald-500/80 pointer-events-none z-10" style={{ left: (realistic.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(realistic.durationDays * DAY_WIDTH, 4), height: 4, top: 6 }} />}

                                {/* MAIN TASK BLOCKS (BROKEN DOWN) */}
                                {task.scheduleDistribution ? Object.entries(task.scheduleDistribution).map(([dateStr, hours]) => {
                                    const offset = getDayOffset(dateStr);
                                    const dayCap = getDayCapacity(dateStr);
                                    const fillPercent = Math.min(100, (hours / (dayCap || 24)) * 100);

                                    return (
                                        <div
                                            key={dateStr}
                                            className={`absolute rounded shadow-sm border flex items-center justify-center z-20 group cursor-help transition-all duration-300 overflow-hidden ${getPhaseColor(task.phase)} ${isDone ? 'opacity-75 saturate-75' : ''}`}
                                            style={{
                                                left: (offset + VISUAL_SHIFT_DAYS) * DAY_WIDTH,
                                                width: DAY_WIDTH - 4,
                                                height: 20,
                                                top: 16,
                                            }}
                                            onMouseEnter={(e) => {
                                                const rect = e.currentTarget.getBoundingClientRect();
                                                setActiveTooltip({
                                                    x: rect.left + (rect.width / 2),
                                                    y: rect.top,
                                                    task,
                                                    realistic,
                                                    dailyInfo: { date: dateStr, hours, capacity: dayCap }
                                                });
                                            }}
                                            onMouseLeave={() => setActiveTooltip(null)}
                                        >
                                             {/* Intensity visualizer (Darker/Lighter background overlay based on capacity usage) */}
                                             <div className="absolute inset-0 bg-white/20 pointer-events-none"></div>
                                             {/* Bar representing fullness (inverted for fill effect) */}
                                             <div 
                                                className="absolute top-0 bottom-0 bg-black/10 dark:bg-black/30 pointer-events-none" 
                                                style={{ left: 0, width: `${fillPercent}%` }}
                                             />

                                             {isDone && <div className="absolute w-full h-[2px] bg-slate-900/50 dark:bg-white/50 z-30 pointer-events-none" />}

                                             {/* Text Label */}
                                             <span className="text-[9px] font-bold text-white z-30 relative drop-shadow-[0_1px_1px_rgba(0,0,0,0.5)]">
                                                 {hours}h
                                             </span>
                                        </div>
                                    );
                                }) : (
                                    /* Fallback if no distribution (shouldn't happen) */
                                    <div className={`absolute rounded shadow-sm border flex items-center justify-center z-20 ${getPhaseColor(task.phase)}`} style={{ left: (task.startOffsetDays + VISUAL_SHIFT_DAYS) * DAY_WIDTH, width: Math.max(task.durationDays * DAY_WIDTH, 4), height: 20, top: 16 }}>
                                        fallback
                                    </div>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
      </div>

      {/* Tooltip */}
      {activeTooltip && typeof document !== 'undefined' && createPortal(
            <div className="fixed z-[9999] pointer-events-none print:hidden" style={{ left: activeTooltip.x, top: activeTooltip.y, transform: 'translate(-50%, -100%)', marginTop: '-8px' }}>
                <div className="bg-slate-900 text-white text-xs rounded-lg p-3 shadow-xl w-52 border border-slate-700">
                    <div className="font-bold mb-1 truncate">{activeTooltip.task.task_name}</div>

                    {activeTooltip.dailyInfo && (
                        <div className="bg-slate-800 -mx-3 -mt-1 mb-2 px-3 py-1 border-b border-slate-700 flex justify-between items-center">
                             <span className="text-slate-400 font-mono">{activeTooltip.dailyInfo.date}</span>
                             <span className="font-bold text-emerald-400">{activeTooltip.dailyInfo.hours}h / {activeTooltip.dailyInfo.capacity}h</span>
                        </div>
                    )}

                    <div className="grid grid-cols-2 gap-2 text-[10px]">
                        <div><span className="block text-slate-500">Total Duration</span>{activeTooltip.task.duration_hours}h</div>
                        <div><span className="block text-slate-500">Phase</span>{activeTooltip.task.phase}</div>
                        <div><span className="block text-slate-500">Start Date</span>{activeTooltip.task.startDate.toLocaleDateString()}</div>
                        <div><span className="block text-slate-500">End Date</span>{activeTooltip.task.endDate.toLocaleDateString()}</div>
                    </div>
                </div>
                <div className="w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-slate-900 mx-auto"></div>
            </div>,
            document.body
       )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { ProjectPlan, DailyLog } from './types';
import { DEFAULT_PROJECT_PLAN } from './constants';
import { ProjectTable } from './components/ProjectTable';
import { ProjectChart } from './components/ProjectChart';
import { WorkloadChart } from './components/WorkloadChart';
import { CapacitySimulatorChart } from './components/CapacitySimulatorChart';
import { GanttChart } from './components/GanttChart';
import { JsonEditor } from './components/JsonEditor';
import { InsightPanel } from './components/InsightPanel'; 
import { ChatBot } from './components/ChatBot';
import { LiveAudioBot } from './components/LiveAudioBot';
import { CloudSyncModal } from './components/CloudSyncModal';
import { calculateProjectSchedule, calculateDailyWorkload } from './utils/scheduler';
import { analyzeProjectPlan } from './utils/insightEngine'; 
import { getSupabase, hasSupabaseConfig } from './utils/supabaseClient';
import { ImageGenerator } from './components/ImageGenerator'; // Assumed component

// CONFIGURATION: The hour (0-23) that marks the start of a new "Business Day".
// Actions before this hour count towards the previous calendar day.
const BUSINESS_DAY_CUTOFF_HOUR = 2; 

const App: React.FC = () => {
  const [projectData, setProjectData] = useState<ProjectPlan>(DEFAULT_PROJECT_PLAN);
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [isCloudModalOpen, setIsCloudModalOpen] = useState(false);
  const [isExportMenuOpen, setIsExportMenuOpen] = useState(false);
  const [weekdayHours, setWeekdayHours] = useState<number>(6);
  const [weekendHours, setWeekendHours] = useState<number>(2);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [bufferPercent, setBufferPercent] = useState<number>(30);

  // LOCK STATE
  const [isLocked, setIsLocked] = useState(false);

  // LIVE TIMER
  const [now, setNow] = useState(new Date());

  // Refs to prevent duplicate auto-saves within the same minute
  const lastSystemSaveDate = useRef<string>('');

  // Helper for input value (YYYY-MM-DD)
  const getInputValue = (date: Date) => {
      return date.getFullYear() + '-' + String(date.getMonth() + 1).padStart(2, '0') + '-' + String(date.getDate()).padStart(2, '0');
  }

  // --- GENERALIZED BUSINESS DAY LOGIC ---
  const getBusinessDate = (date: Date): Date => {
      const d = new Date(date);
      // If the time is between 00:00 and CUTOFF, we roll back to the previous calendar day.
      if (d.getHours() < BUSINESS_DAY_CUTOFF_HOUR) {
          d.setDate(d.getDate() - 1);
      }
      return d;
  };

  // --- NIGHTLY SYSTEM STATUS SAVE ---
  const autoSaveSystemStatus = async (currentData: ProjectPlan) => {
      const client = getSupabase();
      if (!client) return;

      try {
          const payload = {
              project_id: currentData.id,
              data: currentData,
              created_at: new Date().toISOString()
          };

          const { error } = await client.from('system_status').insert(payload);
          if (error) {
              console.error("System Status Auto-save failed:", error);
          } else {
              console.log("System Status snapshot saved to Supabase (Chronological Storage).");
          }
      } catch (e) {
          console.error("System Status Auto-save exception:", e);
      }
  };

  // --- AUTOMATED LOGIC (Using Generalized Business Date) ---
  useEffect(() => {
    const checkAndSnapshotDailyLog = () => {
        const currentTime = new Date();

        // 1. NIGHTLY SYSTEM STATUS CHECK (At 12:00 AM sharp)
        if (currentTime.getHours() === 0 && currentTime.getMinutes() === 0) {
            const dateStr = currentTime.toDateString();
            if (lastSystemSaveDate.current !== dateStr) {
                // Only save if locked and config exists
                if (isLocked && hasSupabaseConfig()) {
                    autoSaveSystemStatus(projectData);
                    lastSystemSaveDate.current = dateStr;
                }
            }
        }

        // 2. DAILY PERFORMANCE LOGIC
        const currentBusinessDate = getBusinessDate(currentTime);
        const reportingDate = new Date(currentBusinessDate);
        reportingDate.setDate(reportingDate.getDate() - 1); 

        const reportingDateStr = getInputValue(reportingDate);
        const existingLogs = projectData.daily_logs || [];
        const hasLog = existingLogs.some(log => log.date === reportingDateStr);

        if (!hasLog) {
            const cutoffTime = new Date(reportingDate);
            cutoffTime.setDate(cutoffTime.getDate() + 1);
            cutoffTime.setHours(BUSINESS_DAY_CUTOFF_HOUR, 0, 0, 0);

            const completedTasks = projectData.tasks.filter(t => {
                if (!t.isCompleted || !t.completionDate) return false;
                const tDate = new Date(t.completionDate);
                return tDate <= cutoffTime;
            });

            const count = completedTasks.length;
            const focusHours = completedTasks.reduce((acc, t) => acc + t.duration_hours, 0);

            // Momentum Score Formula: MIN(100, (Tasks*10 + FocusTimeMins/5))
            const momentum = Math.min(100, (count * 10) + ((focusHours * 60) / 5));

            const newLog: DailyLog = {
                date: reportingDateStr,
                completed_count: count,
                total_focus_hours: focusHours,
                momentum_score: Math.round(momentum),
                timestamp: new Date().toISOString()
            };

            setProjectData(prev => ({
                ...prev,
                daily_logs: [...(prev.daily_logs || []), newLog]
            }));
        }
    };

    // Run check immediately on mount, then every minute
    checkAndSnapshotDailyLog();
    const timer = setInterval(() => {
        setNow(new Date()); 
        checkAndSnapshotDailyLog();
    }, 60000);

    return () => clearInterval(timer);
  }, [projectData, projectData.daily_logs, projectData.tasks, isLocked]);

  // Helper to parse the stored string or default to today
  const getProjectDate = () => {
      if (projectData.project_start_date) {
          const [y, m, d] = projectData.project_start_date.split('-').map(Number);
          return new Date(y, m - 1, d);
      }
      return new Date();
  };

  const projectStartDate = useMemo(() => getProjectDate(), [projectData.project_start_date]);

  // State to trigger condensed views for PDF
  const [isPdfExport, setIsPdfExport] = useState(false);

  // Theme Init & Toggle
  useEffect(() => {
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
        setIsDarkMode(true);
    }
  }, []);

  useEffect(() => {
    if (isDarkMode) {
        document.documentElement.classList.add('dark');
    } else {
        document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  // Date formatting helpers
  const formatDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  const formatShortDate = (date: Date) => {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric'
    });
  };

  // SCHEDULE CALCULATIONS
  const baselineTasksSource = useMemo(() => {
    return projectData.tasks.map(t => ({...t, isCompleted: false}));
  }, [projectData.tasks]);

  const baselineTasks = useMemo(() => {
    return calculateProjectSchedule(baselineTasksSource, weekdayHours, weekendHours, projectStartDate, undefined);
  }, [baselineTasksSource, weekdayHours, weekendHours, projectStartDate]);

  const baselineRealisticTasks = useMemo(() => {
    const realisticTasksSource = baselineTasksSource.map(t => ({
        ...t,
        duration_hours: t.duration_hours * (1 + (bufferPercent / 100))
    }));
    return calculateProjectSchedule(realisticTasksSource, weekdayHours, weekendHours, projectStartDate, undefined);
  }, [baselineTasksSource, weekdayHours, weekendHours, bufferPercent, projectStartDate]);

  const baselineMaxVelocityTasks = useMemo(() => {
    return calculateProjectSchedule(baselineTasksSource, 10, 5, projectStartDate, undefined);
  }, [baselineTasksSource, projectStartDate]);

  const processedTasks = useMemo(() => {
    return calculateProjectSchedule(projectData.tasks, weekdayHours, weekendHours, projectStartDate, now);
  }, [projectData.tasks, weekdayHours, weekendHours, projectStartDate, now]);

  const processedRealisticTasks = useMemo(() => {
    const realisticTasksSource = projectData.tasks.map(t => ({
        ...t,
        duration_hours: t.duration_hours * (1 + (bufferPercent / 100))
    }));
    const live = calculateProjectSchedule(realisticTasksSource, weekdayHours, weekendHours, projectStartDate, now);
    return live.map(t => {
        if (t.isCompleted) {
            const shadow = baselineRealisticTasks.find(b => b.id === t.id);
            if (shadow) {
                return {
                    ...t,
                    startDate: shadow.startDate,
                    endDate: shadow.endDate,
                    startOffsetDays: shadow.startOffsetDays,
                    durationDays: shadow.durationDays
                };
            }
        }
        return t;
    });
  }, [projectData.tasks, weekdayHours, weekendHours, bufferPercent, projectStartDate, now, baselineRealisticTasks]);

  const processedMaxVelocityTasks = useMemo(() => {
    const live = calculateProjectSchedule(projectData.tasks, 10, 5, projectStartDate, now);
    return live.map(t => {
        if (t.isCompleted) {
            const shadow = baselineMaxVelocityTasks.find(b => b.id === t.id);
            if (shadow) {
                return {
                    ...t,
                    startDate: shadow.startDate,
                    endDate: shadow.endDate,
                    startOffsetDays: shadow.startOffsetDays,
                    durationDays: shadow.durationDays
                };
            }
        }
        return t;
    });
  }, [projectData.tasks, projectStartDate, now, baselineMaxVelocityTasks]);


  const handleTaskToggle = (taskId: string) => {
    setProjectData(prev => ({
        ...prev,
        tasks: prev.tasks.map(t => {
            if (t.id === taskId) {
                const newStatus = !t.isCompleted;
                let completionDateStr: string | undefined = undefined;

                if (newStatus) {
                    const currentTime = new Date();
                    if (currentTime.getHours() < BUSINESS_DAY_CUTOFF_HOUR) {
                            const yesterdayEnd = new Date(currentTime);
                            yesterdayEnd.setDate(yesterdayEnd.getDate() - 1);
                            yesterdayEnd.setHours(23, 59, 59, 0); 
                            completionDateStr = yesterdayEnd.toISOString();
                    } else {
                            completionDateStr = currentTime.toISOString();
                    }
                }
                return { 
                    ...t, 
                    isCompleted: newStatus,
                    completionDate: completionDateStr
                };
            }
            return t;
        })
    }));
  };

  const dailyWorkload = useMemo(() => {
    return calculateDailyWorkload(processedTasks, weekdayHours, weekendHours);
  }, [processedTasks, weekdayHours, weekendHours]);

  const analysis = useMemo(() => {
    return analyzeProjectPlan(projectData.tasks, weekdayHours, weekendHours, bufferPercent);
  }, [projectData.tasks, weekdayHours, weekendHours, bufferPercent]);

  const calculatedTotalHours = projectData.tasks.reduce((acc, t) => acc + t.duration_hours, 0);

  const finishDate = processedTasks.length > 0 
    ? processedTasks.reduce((max, t) => t.endDate > max ? t.endDate : max, new Date(0)) 
    : new Date();

  const totalDurationDays = Math.ceil((finishDate.getTime() - projectStartDate.getTime()) / (1000 * 60 * 60 * 24));

  const realisticFinishDate = processedRealisticTasks.length > 0 
    ? processedRealisticTasks.reduce((max, t) => t.endDate > max ? t.endDate : max, new Date(0)) 
    : new Date();

  const realisticDurationDays = Math.ceil((realisticFinishDate.getTime() - projectStartDate.getTime()) / (1000 * 60 * 60 * 24));

  // --- Export Handlers ---

  const handleExportJSON = () => {
    const dataStr = JSON.stringify(projectData, null, 2);
    const blob = new Blob([dataStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `dotrackit-plan-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setIsExportMenuOpen(false);
  };

  const handleExportCSV = () => {
    const headers = ["ID", "Phase", "Task Name", "Duration (Hours)", "Start Date", "End Date", "Predecessors", "Completed", "Completion Date"];
    const rows = processedTasks.map(t => [
      t.id,
      `"${t.phase.replace(/"/g, '""')}"`,
      `"${t.task_name.replace(/"/g, '""')}"`,
      t.duration_hours,
      t.startDate.toLocaleDateString(),
      t.endDate.toLocaleDateString(),
      `"${t.predecessors.join(',')}"`,
      t.isCompleted ? "Yes" : "No",
      t.completionDate ? new Date(t.completionDate).toLocaleDateString() : ""
    ]);
    const csvContent = [headers.join(","), ...rows.map(r => r.join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `dotrackit-schedule-${new Date().toISOString().split('T')[0]}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    setIsExportMenuOpen(false);
  };

  const handleExportPDF = () => {
    setIsExportMenuOpen(false);

    // @ts-ignore
    if (!window.html2pdf) {
        alert('PDF generator is loading. Please try again in a moment.');
        return;
    }

    // 1. Capture current theme state
    const wasDarkMode = isDarkMode;

    // 2. Force Light Mode for clean printing
    if (wasDarkMode) {
        setIsDarkMode(false);
    }

    // 3. Enable PDF View Mode
    setIsPdfExport(true);
    const element = document.querySelector('main');
    if (!element) return;
    element.classList.add('pdf-export-mode');

    // 4. Wait for DOM & Re-renders (800ms to be safe for Recharts animation clearing)
    setTimeout(() => {
        const opt = {
            margin: [5, 5, 5, 5], 
            filename: `dotrackit-report-${new Date().toISOString().split('T')[0]}.pdf`,
            image: { type: 'jpeg', quality: 0.98 },
            html2canvas: { 
                scale: 2, 
                useCORS: true, 
                logging: false,
                windowWidth: 800, // Matches our strict CSS width
                width: 800,
                x: 0 // Force start from origin
            },
            jsPDF: { unit: 'mm', format: 'letter', orientation: 'portrait' },
            pagebreak: { mode: ['css', 'legacy'] }
        };

        // @ts-ignore
        window.html2pdf().set(opt).from(element).save().then(() => {
            // Cleanup
            element.classList.remove('pdf-export-mode');
            setIsPdfExport(false);
            if (wasDarkMode) setIsDarkMode(true); // Restore theme
        }).catch((err: any) => {
            console.error("PDF Export failed", err);
            element.classList.remove('pdf-export-mode');
            setIsPdfExport(false);
            if (wasDarkMode) setIsDarkMode(true); // Restore theme
            alert("Failed to generate PDF. Please try the Print option.");
        });
    }, 800); 
  };

  const handlePrint = () => {
    setIsExportMenuOpen(false);
    setTimeout(() => {
        window.print();
    }, 100);
  };

  return (
    <div className="min-h-screen pb-12 print:pb-0 bg-slate-50 dark:bg-slate-950 transition-colors duration-200">
      {/* Navigation / Header */}
      <header className="bg-slate-900 text-white shadow-md sticky top-0 z-40 print:hidden dark:bg-slate-900 dark:border-b dark:border-slate-800">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-500 p-1.5 rounded text-white">
                <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M9 12.75L11.25 15 15 9.75M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
            </div>
            <h1 className="text-xl font-bold tracking-tight">doTrackit <span className="text-indigo-400 font-light">Dashboard</span></h1>
          </div>

          <div className="flex items-center gap-3">
             {/* Cloud Sync Button */}
             <button 
                onClick={() => setIsCloudModalOpen(true)}
                className="hidden md:flex items-center gap-2 px-3 py-1.5 rounded text-sm font-bold bg-emerald-600 hover:bg-emerald-500 text-white transition-colors"
                title="Save/Load from Cloud"
             >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-4 h-4">
                  <path fillRule="evenodd" d="M5.5 17a4.5 4.5 0 01-1.44-8.765 4.5 4.5 0 018.302-3.046 3.5 3.5 0 014.504 4.272A4 4 0 0115 17H5.5zm3.75-2.75a.75.75 0 001.5 0V9.66l1.95 2.1a.75.75 0 101.1-1.02l-3.25-3.5a.75.75 0 00-1.1 0l-3.25 3.5a.75.75 0 101.1 1.02l1.95-2.1v4.59z" clipRule="evenodd" />
                </svg>
                Cloud Sync
             </button>

             {/* Theme Toggle */}
             <button 
                onClick={toggleTheme}
                className="text-slate-400 hover:text-white p-1.5 rounded-full hover:bg-slate-800 transition-colors mr-1"
                title={isDarkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
            >
                {isDarkMode ? (
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M12 3v2.25m6.364.386l-1.591 1.591M21 12h-2.25m-.386 6.364l-1.591-1.591M12 18.75V21m-4.773-4.227l-1.591 1.591M5.25 12H3m4.227-4.773L5.636 5.636M15.75 12a3.75 3.75 0 11-7.5 0 3.75 3.75 0 017.5 0z" />
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                        <path strokeLinecap="round" strokeLinejoin="round" d="M21.752 15.002A9.718 9.718 0 0118 15.75c-5.385 0-9.75-4.365-9.75-9.75 0-1.33.266-2.597.748-3.752A9.753 9.753 0 003 11.25C3 16.635 7.365 21 12.75 21a9.753 9.753 0 009.002-5.998z" />
                    </svg>
                )}
            </button>

             {/* Lock Goal Button */}
             <button 
                onClick={() => setIsLocked(!isLocked)}
                className={`hidden md:flex items-center gap-2 px-3 py-1.5 rounded text-sm font-bold transition-all border ${
                    isLocked 
