                        <div className="mt-2 pt-1 border-t border-slate-100 dark:border-slate-700 flex justify-between gap-4">
                            <span className="text-slate-500 dark:text-slate-400">Total: {item.hours}h</span>
                            <span className="text-slate-400 dark:text-slate-500">Limit: {item.limit}h</span>
                        </div>

                        {item.hours > item.limit && (
                          <p className="text-red-500 font-bold mt-1 text-right">Overloaded!</p>
                        )}
                      </div>
                    );
                  }
                  return null;
                }}
              />

              {phases.map(phase => (
                  <Bar 
                      key={phase} 
                      dataKey={phase} 
                      stackId="a" 
                      fill={getPhaseColor(phase)} 
                      animationDuration={500}
                  />
              ))}

            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

import React, { useMemo } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
  LabelList
} from 'recharts';
import { Task } from '../types';
import { calculateProjectSchedule } from '../utils/scheduler';

interface CapacitySimulatorChartProps {
  tasks: Task[];
  currentWeekday: number;
  currentWeekend: number;
  isDarkMode?: boolean;
  bufferPercent: number;
  onBufferChange: (val: number) => void;
  startDate?: Date;
  readOnly?: boolean;
}

export const CapacitySimulatorChart: React.FC<CapacitySimulatorChartProps> = ({ 
  tasks, 
  currentWeekday, 
  currentWeekend,
  isDarkMode = false,
  bufferPercent,
  onBufferChange,
  startDate,
  readOnly = false
}) => {
  // Local state removed, using props instead

  const data = useMemo(() => {
    // Helper to calc duration
    const getDuration = (wkDay: number, wkEnd: number, taskList: Task[] = tasks) => {
      // Pass the startDate to the scheduler
      const schedule = calculateProjectSchedule(taskList, wkDay, wkEnd, startDate);
      if (schedule.length === 0) return { days: 0, date: new Date() };

      const start = schedule[0].startDate.getTime();
      const end = Math.max(...schedule.map(t => t.endDate.getTime()));
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
      return { days, date: new Date(end) };
    };

    // 1. Realistic Plan (Current Settings + Adjustable Buffer)
    const bufferedTasks = tasks.map(t => ({
        ...t,
        duration_hours: t.duration_hours * (1 + (bufferPercent / 100))
    }));
    // Use currentWeekday/currentWeekend so that 0% buffer matches Current Plan exactly
    const realistic = getDuration(currentWeekday, currentWeekend, bufferedTasks);

    // 2. Current Settings (Raw estimates)
    const current = getDuration(currentWeekday, currentWeekend);

    // 3. Max Velocity (Hustle, Raw estimates)
    const hustle = getDuration(10, 5);

    return [
      {
        name: 'Realistic Plan',
        desc: `Current + ${bufferPercent}% Buffer`,
        days: realistic.days,
        date: realistic.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#10b981', // emerald-500
        opacity: 0.7
      },
      {
        name: 'Current Plan',
        desc: `${currentWeekday}h/day, ${currentWeekend}h Wknds`,
        days: current.days,
        date: current.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#3b82f6', // blue-500
        opacity: 1
      },
      {
        name: 'Max Velocity',
        desc: '10h/day, 5h Wknds',
        days: hustle.days,
        date: hustle.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#f43f5e', // rose-500
        opacity: 0.8
      }
    ];
  }, [tasks, currentWeekday, currentWeekend, bufferPercent, startDate]);

  const axisColor = isDarkMode ? '#94a3b8' : '#64748b';
  const gridColor = isDarkMode ? '#334155' : '#e2e8f0';

  return (
    <div className="bg-white dark:bg-slate-900 p-6 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 h-80 flex flex-col w-full">
      <div className="flex justify-between items-start mb-2">
        <div>
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            Schedule Scenarios
            {readOnly && (
               <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 text-[10px] px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700">LOCKED</span>
            )}
          </h3>
          <p className="text-xs text-slate-500 dark:text-slate-400">Compare delivery speeds.</p>
        </div>

        {/* Buffer Input - Interactive */}
        <div className={`flex flex-col items-end ${readOnly ? 'opacity-50 pointer-events-none grayscale' : ''}`}>
            <label className="text-[10px] uppercase font-bold text-slate-400 mb-1">Safety Buffer %</label>
            <div className="flex items-center gap-2">
                <input 
                    type="range"
                    min="0"
                    max="100"
                    step="5"
                    disabled={readOnly}
                    value={bufferPercent}
                    onChange={(e) => onBufferChange(parseInt(e.target.value))}
                    className="w-24 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-600 disabled:cursor-not-allowed"
                />
                <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 min-w-[30px] text-right">
                    {bufferPercent}%
                </span>
            </div>
        </div>
      </div>

      <div className="flex-1 min-h-0 min-w-0 relative">
        <div className="absolute inset-0">
          <ResponsiveContainer width="99%" height="100%" minWidth={0} minHeight={0} debounce={200}>
            <BarChart
              layout="vertical"
              data={data}
              margin={{ top: 10, right: 60, left: 10, bottom: 5 }}
              barCategoryGap={20}
            >
              <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={true} stroke={gridColor} />
              <XAxis type="number" hide />
              <YAxis 
                dataKey="name" 
                type="category" 
                width={85} 
                tick={{ fontSize: 11, fill: axisColor, fontWeight: 600 }}
                interval={0}
              />
              <Tooltip
                cursor={{ fill: 'transparent' }}
                content={({ active, payload }) => {
                  if (active && payload && payload.length) {
                    const d = payload[0].payload;
                    return (
                      <div className="bg-white dark:bg-slate-800 p-2 border border-slate-200 dark:border-slate-700 shadow-lg rounded text-xs z-50">
                        <div className="font-bold text-slate-800 dark:text-slate-200">{d.name}</div>
                        <div className="text-slate-500 dark:text-slate-400 mb-1">{d.desc}</div>
                        <div className="flex justify-between gap-4 border-t border-slate-100 dark:border-slate-700 pt-1 mt-1">
                          <span className="text-slate-600 dark:text-slate-400">Duration:</span>
                          <span className="font-mono font-bold text-slate-800 dark:text-slate-200">{d.days} Days</span>
                        </div>
                        <div className="flex justify-between gap-4">
                          <span className="text-slate-600 dark:text-slate-400">Launch:</span>
                          <span className="font-mono font-bold text-indigo-600 dark:text-indigo-400">{d.date}</span>
                        </div>
                      </div>
                    );
                  }
                  return null;
                }}
              />
              <Bar dataKey="days" radius={[0, 4, 4, 0]} barSize={32}>
                {data.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} fillOpacity={entry.opacity} />
                ))}
                <LabelList 
                  dataKey="date" 
                  position="right" 
                  style={{ fontSize: '11px', fontWeight: 'bold', fill: isDarkMode ? '#94a3b8' : '#475569' }} 
                />
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        {/* Comparison Text Overlay */}
        <div className="absolute bottom-2 right-2 text-[10px] text-slate-400 dark:text-slate-500 italic bg-white/80 dark:bg-slate-900/80 px-2 rounded">
            Working "Max Velocity" saves {Math.max(0, data[1].days - data[2].days)} days vs Current.
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

interface ImageGeneratorProps {
  initialPrompt: string;
}

export const ImageGenerator: React.FC<ImageGeneratorProps> = ({ initialPrompt }) => {
  const [prompt, setPrompt] = useState(initialPrompt);
  const [imageSize, setImageSize] = useState<'1K' | '2K' | '4K'>('1K');
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    setPrompt(initialPrompt);
  }, [initialPrompt]);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      // @ts-ignore
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
         // @ts-ignore
         const hasKey = await window.aistudio.hasSelectedApiKey();
         if (!hasKey) {
            // @ts-ignore
            await window.aistudio.openSelectKey();
         }
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-image-preview',
        contents: {
          parts: [{ text: `A high quality, professional, futuristic concept visualization for a project with this goal: ${prompt}` }],
        },
        config: {
          imageConfig: {
            imageSize: imageSize
          }
        },
      });

      const parts = response.candidates?.[0]?.content?.parts;
      let base64Image = null;
      let mimeType = 'image/png';

      if (parts) {
        for (const part of parts) {
            if (part.inlineData) {
                base64Image = part.inlineData.data;
                mimeType = part.inlineData.mimeType || 'image/png';
                break;
            }
        }
      }

      if (base64Image) {
        setImageUrl(`data:${mimeType};base64,${base64Image}`);
        if (!isOpen) setIsOpen(true); // Auto-open on success if closed
      } else {
        setError('No image returned. Try a different prompt.');
      }

    } catch (err: any) {
        console.error(err);
        if (err.message && err.message.includes("Requested entity was not found")) {
             // @ts-ignore
             if (window.aistudio && window.aistudio.openSelectKey) {
                 // @ts-ignore
                 await window.aistudio.openSelectKey();
             }
             setError("API Key session issue. Please try again.");
        } else {
            setError(err.message || 'Generation failed');
        }
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = () => {
    if (!imageUrl) return;
    const link = document.createElement('a');
    link.href = imageUrl;
    link.download = `project-visualization-${new Date().getTime()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <section className="bg-white dark:bg-slate-900 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 mb-8 break-inside-avoid overflow-hidden transition-all duration-300">

      {/* Header / Toggle */}
      <div 
        onClick={() => setIsOpen(!isOpen)}
        className={`px-6 py-4 flex items-center justify-between cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors ${isOpen ? 'border-b border-slate-200 dark:border-slate-800' : ''}`}
      >
        <div className="flex items-center gap-3">
             <div className="bg-indigo-100 dark:bg-indigo-900/30 p-1.5 rounded text-indigo-600 dark:text-indigo-400">
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M1.5 6a2.25 2.25 0 0 1 2.25-2.25h16.5A2.25 2.25 0 0 1 22.5 6v12a2.25 2.25 0 0 1-2.25 2.25H3.75A2.25 2.25 0 0 1 1.5 18V6ZM3 16.06V18c0 .414.336.75.75.75h16.5A.75.75 0 0 0 21 18v-1.94l-2.69-2.689a1.5 1.5 0 0 0-2.12 0l-.88.879.97.97a.75.75 0 1 1-1.06 1.06l-5.16-5.159a1.5 1.5 0 0 0-2.12 0L3 16.061Zm10.125-7.81a1.125 1.125 0 1 1 2.25 0 1.125 1.125 0 0 1-2.25 0Z" clipRule="evenodd" />
                </svg>
             </div>
             <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100">Project Visualization</h3>
        </div>

        <div className="flex items-center gap-4">
             {imageUrl && !isOpen && (
                 <span className="text-[10px] bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400 px-2 py-0.5 rounded font-bold uppercase tracking-wide">
                     Image Ready
                 </span>
             )}
             <div className={`text-slate-400 dark:text-slate-500 transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}>
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-5 h-5">
                    <path fillRule="evenodd" d="M5.23 7.21a.75.75 0 011.06.02L10 11.168l3.71-3.938a.75.75 0 111.08 1.04l-4.25 4.5a.75.75 0 01-1.08 0l-4.25-4.5a.75.75 0 01.02-1.06z" clipRule="evenodd" />
                </svg>
            </div>
        </div>
      </div>

      {isOpen && (
        <div className="p-6 animate-fade-in">
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center mb-4 gap-4">
                <div className="text-sm text-slate-500 dark:text-slate-400">
                    Generate a concept visualization based on your project goal.
                </div>
                <div className="flex items-center gap-3 w-full sm:w-auto print:hidden">
                    <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 rounded px-2 py-1 border border-slate-200 dark:border-slate-700">
                        <span className="text-[10px] font-bold text-slate-500 uppercase">Size</span>
                        <select 
                            value={imageSize} 
                            onChange={(e) => setImageSize(e.target.value as any)}
                            className="text-xs font-mono font-bold bg-transparent text-slate-800 dark:text-slate-200 focus:outline-none cursor-pointer"
                        >
                            <option value="1K">1K</option>
                            <option value="2K">2K</option>
