                    dataKey="label" 
                    stroke={axisColor} 
                    fontSize={11} 
                    tickMargin={5}
                    interval="preserveStartEnd"
                />
                <YAxis 
                    stroke={axisColor} 
                    fontSize={11}
                    width={30}
                    label={{ value: 'Hours', angle: -90, position: 'insideLeft', style: { fill: axisColor, fontSize: 10 } }}
                />
                <Tooltip
                    cursor={{ fill: isDarkMode ? '#1e293b' : '#f1f5f9' }}
                    content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                        const item = payload[0].payload as DailyWorkload;
                        // Sort payload by value desc to show biggest contributors first
                        const sortedPayload = [...payload].sort((a, b) => Number(b.value) - Number(a.value));

                        return (
                        <div className="bg-white dark:bg-slate-800 p-3 border border-slate-200 dark:border-slate-700 shadow-lg rounded-lg text-xs z-50">
                            <p className="font-bold text-slate-800 dark:text-slate-200 mb-1 border-b border-slate-100 dark:border-slate-700 pb-1">{item.tooltipLabel}</p>

                            {sortedPayload.map((entry: any) => (
                                <div key={entry.name} className="flex items-center gap-2 mb-0.5">
                                    <div className="w-2 h-2 rounded-full" style={{ backgroundColor: entry.color }}></div>
                                    <span className="text-slate-600 dark:text-slate-300 font-medium">{entry.name}:</span>
                                    <span className="text-slate-900 dark:text-slate-100 font-bold">{entry.value}h</span>
                                </div>
                            ))}

                            <div className="mt-2 pt-1 border-t border-slate-100 dark:border-slate-700 flex justify-between gap-4">
                                <span className="text-slate-500 dark:text-slate-400">Total: {item.hours}h</span>
                                <span className="text-slate-400 dark:text-slate-500">Limit: {item.limit}h</span>
                            </div>

                            {item.hours > item.limit && (
                            <p className="text-red-500 font-bold mt-1 text-right">Overloaded!</p>
                            )}
                        </div>
                        );
                    }
                    return null;
                    }}
                />

                {phases.map(phase => (
                    <Bar 
                        key={phase} 
                        dataKey={phase} 
                        stackId="a" 
                        fill={getPhaseColor(phase)} 
                        animationDuration={500}
                    />
                ))}

                </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="w-full h-full flex items-center justify-center">
                <div className="w-5 h-5 border-2 border-slate-200 border-t-indigo-500 rounded-full animate-spin"></div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useMemo, useState, useEffect } from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
  LabelList
} from 'recharts';
import { Task } from '../types';
import { calculateProjectSchedule } from '../utils/scheduler';

interface CapacitySimulatorChartProps {
  tasks: Task[];
  currentWeekday: number;
  currentWeekend: number;
  isDarkMode?: boolean;
  bufferPercent: number;
  onBufferChange: (val: number) => void;
  startDate?: Date;
  readOnly?: boolean;
}

export const CapacitySimulatorChart: React.FC<CapacitySimulatorChartProps> = ({ 
  tasks, 
  currentWeekday, 
  currentWeekend,
  isDarkMode = false,
  bufferPercent,
  onBufferChange,
  startDate,
  readOnly = false
}) => {
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    setIsMounted(true);
  }, []);

  const data = useMemo(() => {
    // Helper to calc duration
    const getDuration = (wkDay: number, wkEnd: number, taskList: Task[] = tasks) => {
      // Pass the startDate to the scheduler
      const schedule = calculateProjectSchedule(taskList, wkDay, wkEnd, startDate);
      if (schedule.length === 0) return { days: 0, date: new Date() };

      const start = schedule[0].startDate.getTime();
      const end = Math.max(...schedule.map(t => t.endDate.getTime()));
      const days = Math.ceil((end - start) / (1000 * 60 * 60 * 24));
      return { days, date: new Date(end) };
    };

    // 1. Realistic Plan (Current Settings + Adjustable Buffer)
    const bufferedTasks = tasks.map(t => ({
        ...t,
        duration_hours: t.duration_hours * (1 + (bufferPercent / 100))
    }));
    // Use currentWeekday/currentWeekend so that 0% buffer matches Current Plan exactly
    const realistic = getDuration(currentWeekday, currentWeekend, bufferedTasks);

    // 2. Current Settings (Raw estimates)
    const current = getDuration(currentWeekday, currentWeekend);

    // 3. Max Velocity (Hustle, Raw estimates)
    const hustle = getDuration(10, 5);

    return [
      {
        name: 'Realistic Plan',
        desc: `Current + ${bufferPercent}% Buffer`,
        days: realistic.days,
        date: realistic.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#10b981', // emerald-500
        opacity: 0.7
      },
      {
        name: 'Current Plan',
        desc: `${currentWeekday}h/day, ${currentWeekend}h Wknds`,
        days: current.days,
        date: current.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#3b82f6', // blue-500
        opacity: 1
      },
      {
        name: 'Max Velocity',
        desc: '10h/day, 5h Wknds',
        days: hustle.days,
        date: hustle.date.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }),
        color: '#f43f5e', // rose-500
        opacity: 0.8
      }
    ];
  }, [tasks, currentWeekday, currentWeekend, bufferPercent, startDate]);

  const axisColor = isDarkMode ? '#94a3b8' : '#64748b';
  const gridColor = isDarkMode ? '#334155' : '#e2e8f0';

  return (
    <div className="bg-white dark:bg-slate-900 p-6 rounded-lg shadow-sm border border-slate-200 dark:border-slate-800 h-80 flex flex-col w-full">
      <div className="flex justify-between items-start mb-2">
        <div>
          <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 flex items-center gap-2">
            Schedule Scenarios
            {readOnly && (
               <span className="bg-slate-100 dark:bg-slate-800 text-slate-500 text-[10px] px-1.5 py-0.5 rounded border border-slate-200 dark:border-slate-700">LOCKED</span>
            )}
          </h3>
          <p className="text-xs text-slate-500 dark:text-slate-400">Compare delivery speeds.</p>
        </div>

        {/* Buffer Input - Interactive */}
        <div className={`flex flex-col items-end ${readOnly ? 'opacity-50 pointer-events-none grayscale' : ''}`}>
            <label className="text-[10px] uppercase font-bold text-slate-400 mb-1">Safety Buffer %</label>
            <div className="flex items-center gap-2">
                <input 
                    type="range"
                    min="0"
                    max="100"
                    step="5"
                    disabled={readOnly}
                    value={bufferPercent}
                    onChange={(e) => onBufferChange(parseInt(e.target.value))}
                    className="w-24 h-1.5 bg-slate-200 dark:bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-600 disabled:cursor-not-allowed"
                />
                <span className="text-xs font-bold text-indigo-600 dark:text-indigo-400 min-w-[30px] text-right">
                    {bufferPercent}%
                </span>
            </div>
        </div>
      </div>

      <div className="flex-1 min-h-0 min-w-0 relative">
        <div className="absolute inset-0">
          {isMounted ? (
            <ResponsiveContainer width="100%" height="100%" debounce={50}>
                <BarChart
                layout="vertical"
                data={data}
                margin={{ top: 10, right: 60, left: 10, bottom: 5 }}
                barCategoryGap={20}
                >
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={true} stroke={gridColor} />
                <XAxis type="number" hide />
                <YAxis 
                    dataKey="name" 
                    type="category" 
                    width={85} 
                    tick={{ fontSize: 11, fill: axisColor, fontWeight: 600 }}
                    interval={0}
                />
                <Tooltip
                    cursor={{ fill: 'transparent' }}
                    content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                        const d = payload[0].payload;
                        return (
                        <div className="bg-white dark:bg-slate-800 p-2 border border-slate-200 dark:border-slate-700 shadow-lg rounded text-xs z-50">
                            <div className="font-bold text-slate-800 dark:text-slate-200">{d.name}</div>
                            <div className="text-slate-500 dark:text-slate-400 mb-1">{d.desc}</div>
                            <div className="flex justify-between gap-4 border-t border-slate-100 dark:border-slate-700 pt-1 mt-1">
                            <span className="text-slate-600 dark:text-slate-400">Duration:</span>
                            <span className="font-mono font-bold text-slate-800 dark:text-slate-200">{d.days} Days</span>
                            </div>
                            <div className="flex justify-between gap-4">
                            <span className="text-slate-600 dark:text-slate-400">Launch:</span>
                            <span className="font-mono font-bold text-indigo-600 dark:text-indigo-400">{d.date}</span>
                            </div>
                        </div>
                        );
                    }
                    return null;
                    }}
                />
                <Bar dataKey="days" radius={[0, 4, 4, 0]} barSize={32}>
                    {data.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} fillOpacity={entry.opacity} />
                    ))}
                    <LabelList 
                    dataKey="date" 
                    position="right" 
                    style={{ fontSize: '11px', fontWeight: 'bold', fill: isDarkMode ? '#94a3b8' : '#475569' }} 
                    />
                </Bar>
                </BarChart>
            </ResponsiveContainer>
          ) : (
            <div className="w-full h-full flex items-center justify-center">
                <div className="w-5 h-5 border-2 border-slate-200 border-t-indigo-500 rounded-full animate-spin"></div>
            </div>
          )}
        </div>

        {/* Comparison Text Overlay */}
        <div className="absolute bottom-2 right-2 text-[10px] text-slate-400 dark:text-slate-500 italic bg-white/80 dark:bg-slate-900/80 px-2 rounded">
            Working "Max Velocity" saves {Math.max(0, data[1].days - data[2].days)} days vs Current.
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Chat } from "@google/genai";
import { ProjectPlan, ProcessedTask } from '../types';

interface ChatBotProps {
  projectPlan: ProjectPlan;
  processedTasks: ProcessedTask[];
}

interface Message {
  role: 'user' | 'model';
  text: string;
}

export const ChatBot: React.FC<ChatBotProps> = ({ projectPlan, processedTasks }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: 'Hi! I\'m your AI Project Boss. Ask me anything about your plan.' }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const chatSession = useRef<Chat | null>(null);

  // Invalidate chat session when plan context changes significantly
  useEffect(() => {
     chatSession.current = null;
  }, [projectPlan, processedTasks]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages, isOpen]);

  const initializeChat = async () => {
    try {
        // @ts-ignore
        if (window.aistudio && window.aistudio.hasSelectedApiKey) {
             // @ts-ignore
             const hasKey = await window.aistudio.hasSelectedApiKey();
             if (!hasKey) {
                // @ts-ignore
                await window.aistudio.openSelectKey();
             }
        }

        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Prepare context summary
        const scheduleContext = processedTasks.map(t => ({
            id: t.id,
            name: t.task_name,
            phase: t.phase,
            start: t.startDate.toDateString(),
            end: t.endDate.toDateString(),
            duration: t.duration_hours,
            predecessors: t.predecessors
        }));

        const contextStr = JSON.stringify({
            goal: projectPlan.smart_goal,
            totalEstHours: projectPlan.total_estimated_duration_hours,
            schedule: scheduleContext
        });

        chatSession.current = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: {
                systemInstruction: `You are an AI Project Manager for the app 'doTrackit'.
                Your goal is to help the user execute their project.

                Current Project Context:
                ${contextStr}

                Guidelines:
                1. Answer questions about dates, dependencies, and risks based on the Schedule provided.
                2. Be concise, direct, and encouraging but realistic ("tough love").
                3. If the user asks to change the plan, guide them to use the Edit Data button, as you cannot modify the plan directly yet.
                `
            }
        });
        return true;

    } catch (error: any) {
        console.error("Failed to init AI chat", error);
        if (error.message && error.message.includes("Requested entity was not found")) {
            // @ts-ignore
             if (window.aistudio && window.aistudio.openSelectKey) {
                 // @ts-ignore
                 await window.aistudio.openSelectKey();
             }
             setMessages(prev => [...prev, { role: 'model', text: "API Key Required. Please select a key and try again." }]);
        } else {
             setMessages(prev => [...prev, { role: 'model', text: "Connection error: " + (error.message || "Unknown") }]);
        }
        return false;
    }
  };

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsLoading(true);

    try {
      // Lazy initialization
      if (!chatSession.current) {
         const success = await initializeChat();
         if (!success) {
             setIsLoading(false);
             return;
         }
      }

      if (chatSession.current) {
        const response = await chatSession.current.sendMessage({ message: userMessage });
        const text = response.text;
        setMessages(prev => [...prev, { role: 'model', text: text || "I didn't have a response." }]);
      }
    } catch (error) {
      console.error("Gemini Error:", error);
      setMessages(prev => [...prev, { role: 'model', text: "I lost the connection. Please try again." }]);
      chatSession.current = null; // Reset on error
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <>
      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-6 right-6 bg-indigo-600 hover:bg-indigo-700 text-white p-4 rounded-full shadow-2xl z-50 transition-transform hover:scale-105 print:hidden"
        title="Ask AI Boss"
      >
        {isOpen ? (
           <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
            <path strokeLinecap="round" strokeLinejoin="round" d="M8.625 12a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H8.25m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0H12m4.125 0a.375.375 0 11-.75 0 .375.375 0 01.75 0zm0 0h-.375M21 12c0 4.556-4.03 8.25-9 8.25a9.764 9.764 0 01-2.555-.337A5.972 5.972 0 015.41 20.97a5.969 5.969 0 01-.474-.065 4.48 4.48 0 00.978-2.025c.09-.457-.133-.901-.467-1.226C3.93 16.178 3 14.189 3 12c0-4.556 4.03-8.25 9-8.25s9 3.694 9 8.25z" />
          </svg>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="fixed bottom-24 right-6 w-96 h-[500px] bg-white dark:bg-slate-900 rounded-xl shadow-2xl border border-slate-200 dark:border-slate-800 z-50 flex flex-col overflow-hidden animate-fade-in print:hidden">
            <div className="bg-slate-900 dark:bg-slate-950 p-4 text-white flex justify-between items-center">
                <div className="font-bold flex items-center gap-2">
                    <span className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></span>
                    AI Boss
                </div>
                <div className="flex flex-col items-end">
                    <span className="text-[10px] text-slate-400">Powered by Gemini</span>
                    <span className="text-[9px] text-indigo-400 bg-indigo-900/50 px-1 rounded">3.0 Pro</span>
                </div>
            </div>

            <div className="flex-1 p-4 overflow-y-auto bg-slate-50 dark:bg-slate-800/50 space-y-4">
                {messages.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div 
                            className={`max-w-[85%] rounded-2xl px-4 py-2.5 text-sm ${
                                msg.role === 'user' 
                                ? 'bg-indigo-600 text-white rounded-br-sm' 
                                : 'bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 rounded-bl-sm shadow-sm'
                            }`}
                            style={{ color: msg.role === 'user' ? '#ffffff' : '' }}
                        >
                            {msg.text}
                        </div>
                    </div>
                ))}
                {isLoading && (
                    <div className="flex justify-start">
                        <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-500 dark:text-slate-400 rounded-2xl px-4 py-3 text-sm shadow-sm flex items-center gap-2">
                            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></span>
                            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-100"></span>
                            <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-200"></span>
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            <div className="p-4 bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800">
                <div className="flex gap-2">
                    <input
                        type="text"
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                        placeholder="Ask about dates, risks..."
                        className="flex-1 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-200 placeholder:text-slate-400 border border-slate-300 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
                        autoFocus
                    />
                    <button 
                        onClick={handleSend}
                        disabled={isLoading || !input.trim()}
                        className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M6 12L3.269 3.126A59.768 59.768 0 0121.485 12 59.77 59.77 0 013.27 20.876L5.999 12zm0 0h7.5" />
                        </svg>
                    </button>
                </div>
            </div>
        </div>
      )}
    </>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, FunctionDeclaration, Type, Blob as GenAIBlob } from '@google/genai';
import { ProjectPlan, ProcessedTask } from '../types';

interface LiveAudioBotProps {
  projectPlan: ProjectPlan;
  processedTasks: ProcessedTask[];
  onTaskToggle: (taskId: string) => void;
}

export const LiveAudioBot: React.FC<LiveAudioBotProps> = ({ 
  projectPlan, 
  processedTasks, 
  onTaskToggle 
}) => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [volume, setVolume] = useState(0);

  // Audio Refs
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const processorRef = useRef<ScriptProcessorNode | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const audioQueueRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const sessionPromiseRef = useRef<Promise<any> | null>(null);

  // Helper to get formatted task context for the AI
  const getContextString = () => {
    const tasks = processedTasks.map(t => 
      `ID: ${t.id}, Name: "${t.task_name}", Status: ${t.isCompleted ? 'Done' : 'Pending'}, Due: ${t.endDate.toLocaleDateString()}`
    ).join('\n');

    return `Project Goal: ${projectPlan.smart_goal}\n\nTasks:\n${tasks}`;
  };

  const startSession = async () => {
    setIsConnecting(true);
    try {
      // @ts-ignore
      if (window.aistudio && window.aistudio.hasSelectedApiKey) {
           // @ts-ignore
           const hasKey = await window.aistudio.hasSelectedApiKey();
           if (!hasKey) {
              // @ts-ignore
              await window.aistudio.openSelectKey();
           }
      }

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // 1. Tool Definition
      const markDoneTool: FunctionDeclaration = {
        name: 'markTaskComplete',
        description: 'Mark a task as completed/done. Use this when the user says they finished something.',
        parameters: {
          type: Type.OBJECT,
          properties: {
            taskId: {
              type: Type.STRING,
              description: 'The exact ID of the task to mark done (e.g., "1", "2").',
            },
          },
          required: ['taskId'],
        },
      };

      // 2. Audio Setup
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      inputAudioContextRef.current = inputCtx;
      outputAudioContextRef.current = outputCtx;

      const outputNode = outputCtx.createGain();
      outputNode.connect(outputCtx.destination);

      // 3. Connect to Gemini Live
      sessionPromiseRef.current = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
          systemInstruction: `You are the "AI Boss", a strict but helpful project manager. 
          You are talking to the user via voice. Keep responses concise (1-2 sentences) as it is a voice conversation.

          Context:
          ${getContextString()}

          If the user completes a task, congratulate them briefly and call the tool 'markTaskComplete'.
          If they ask about consequences, explain dependencies based on the task IDs.`,
          tools: [{ functionDeclarations: [markDoneTool] }],
        },
        callbacks: {
          onopen: async () => {
             console.log("Gemini Live Connected");
             setIsActive(true);
             setIsConnecting(false);

             // Start Mic Stream
             try {
                const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
                streamRef.current = stream;

                const source = inputCtx.createMediaStreamSource(stream);
                const processor = inputCtx.createScriptProcessor(4096, 1, 1);

                sourceRef.current = source;
                processorRef.current = processor;

                processor.onaudioprocess = (e) => {
                    const inputData = e.inputBuffer.getChannelData(0);

                    // Simple Volume Meter
                    let sum = 0;
                    for(let i=0; i<inputData.length; i++) sum += inputData[i] * inputData[i];
                    setVolume(Math.sqrt(sum / inputData.length) * 10); // Scale up

                    const pcmBlob = createBlob(inputData);
                    sessionPromiseRef.current?.then((session) => {
                         session.sendRealtimeInput({ media: pcmBlob });
                    });
                };

                source.connect(processor);
                processor.connect(inputCtx.destination);
             } catch (err) {
                 console.error("Mic Error", err);
                 stopSession();
             }
          },
          onmessage: async (msg: LiveServerMessage) => {
            // 1. Handle Tool Calls (Task Marking)
            if (msg.toolCall) {
                for (const fc of msg.toolCall.functionCalls) {
                    if (fc.name === 'markTaskComplete') {
                        const tId = (fc.args as any).taskId;
                        // Execute locally
                        onTaskToggle(tId);

                        // Tell Model it's done
                        sessionPromiseRef.current?.then((session) => {
                            session.sendToolResponse({
                                functionResponses: {
                                    id: fc.id,
                                    name: fc.name,
                                    response: { result: "Task marked done successfully." }
                                }
                            });
                        });
                    }
                }
            }

            // 2. Handle Audio Output
            const base64Audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio) {
                try {
                    if (outputCtx.state === 'suspended') await outputCtx.resume();

                    const audioBuffer = await decodeAudioData(
                        decode(base64Audio),
                        outputCtx,
                        24000,
                        1
                    );

                    // Basic scheduling to prevent gaps
                    const currentTime = outputCtx.currentTime;
                    if (nextStartTimeRef.current < currentTime) {
                        nextStartTimeRef.current = currentTime;
                    }

                    const source = outputCtx.createBufferSource();
                    source.buffer = audioBuffer;
                    source.connect(outputNode);

                    source.start(nextStartTimeRef.current);
                    nextStartTimeRef.current += audioBuffer.duration;

                    audioQueueRef.current.add(source);
                    source.onended = () => audioQueueRef.current.delete(source);

                } catch (e) {
                    console.error("Audio Decode Error", e);
                }
            }

            // 3. Handle Interruptions
            if (msg.serverContent?.interrupted) {
                audioQueueRef.current.forEach(src => {
                    try { src.stop(); } catch(e){}
                });
                audioQueueRef.current.clear();
                nextStartTimeRef.current = 0;
            }
          },
          onclose: () => {
              console.log("Gemini Live Closed");
              stopSession();
          },
          onerror: (e) => {
              console.error("Gemini Live Error", e);
              stopSession();
          }
        }
      });

    } catch (e) {
      console.error(e);
      setIsConnecting(false);
      // @ts-ignore
      if (e.message && e.message.includes("Requested entity was not found")) {
           // @ts-ignore
           if (window.aistudio && window.aistudio.openSelectKey) {
                // @ts-ignore
                await window.aistudio.openSelectKey();
           }
      }
    }
  };

  const stopSession = () => {
    // Stop Mic
    if (streamRef.current) {
        streamRef.current.getTracks().forEach(t => t.stop());
        streamRef.current = null;
    }
    if (processorRef.current) {
        processorRef.current.disconnect();
        processorRef.current = null;
    }
    if (sourceRef.current) {
        sourceRef.current.disconnect();
        sourceRef.current = null;
    }

    // Stop Output
    if (inputAudioContextRef.current) inputAudioContextRef.current.close();
    if (outputAudioContextRef.current) outputAudioContextRef.current.close();

    // Close Session
    sessionPromiseRef.current?.then(s => s.close()); // No explicit close on chat interface, but good practice if available

    setIsActive(false);
    setIsConnecting(false);
    setVolume(0);
  };

  // --- Audio Utils (From Spec) ---

  function createBlob(data: Float32Array): GenAIBlob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        // Clamp and scale
        let s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s < 0 ? s * 0x8000 : s * 0x7FFF;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
  }

  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  async function decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
  }


  return (
    <>
        <button
            onClick={isActive ? stopSession : startSession}
            disabled={isConnecting}
            className={`fixed bottom-6 right-24 p-4 rounded-full shadow-2xl z-50 transition-all duration-300 print:hidden flex items-center justify-center border-2 border-white/20 ${
                isActive 
                ? 'bg-rose-500 hover:bg-rose-600 scale-110' 
                : 'bg-slate-800 hover:bg-slate-700'
            }`}
            title="Live Voice Mode"
        >
            {isConnecting ? (
                <svg className="animate-spin h-6 w-6 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
            ) : isActive ? (
                // Active State (Waveform visualizer approx)
                <div className="flex items-end gap-1 h-6 w-6 justify-center">
                    <div className="w-1 bg-white rounded-full transition-all duration-75" style={{ height: `${Math.max(20, Math.min(100, volume * 100))}%` }}></div>
                    <div className="w-1 bg-white rounded-full transition-all duration-75" style={{ height: `${Math.max(30, Math.min(100, volume * 150))}%` }}></div>
                    <div className="w-1 bg-white rounded-full transition-all duration-75" style={{ height: `${Math.max(20, Math.min(100, volume * 80))}%` }}></div>
                </div>
            ) : (
                // Mic Icon
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-6 h-6 text-white">
                    <path d="M8.25 4.5a3.75 3.75 0 1 1 7.5 0v8.25a3.75 3.75 0 1 1-7.5 0V4.5Z" />
                    <path d="M6 10.5a.75.75 0 0 1 .75.75v1.5a5.25 5.25 0 1 0 10.5 0v-1.5a.75.75 0 0 1 1.5 0v1.5a6.751 6.751 0 0 1-6 9.375v1.875a.75.75 0 0 1-1.5 0v-1.875A6.751 6.751 0 0 1 5.25 12.75v-1.5a.75.75 0 0 1 .75-.75Z" />
                </svg>
            )}
        </button>

        {isActive && (
             <div className="fixed bottom-24 right-24 bg-rose-600 text-white text-xs font-bold px-3 py-1 rounded-lg shadow-lg z-50 animate-bounce print:hidden">
                 Live Audio Active
             </div>
        )}
    </>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, Chat } from "@google/genai";
